/* DAWAH X — ahmad, অধ্যায় 119 · খণ্ড 119 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][119]=[[23601,23601,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ ‏ ‏الثِّمَارِ حَتَّى يَبْدُوَ ‏ ‏صَلَاحُهَا ‏ ‏وَتَأْمَنَ مِنْ ‏ ‏الْعَاهَةِ ‏","","",""],[23602,23602,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُثْمَانُ ابْنُ عَبْدِ الْمَلِكِ أَبُو قُدَامَةَ الْعُمَرِيُّ ‏ ‏قَالَ حَدَّثَتْنَا ‏ ‏عَائِشَةُ بِنْتُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ ذَرَّةَ ‏ ‏قَالَتْ ‏ ‏رَأَيْتُ ‏ ‏عَائِشَةَ ‏ ‏تُصَلِّي الضُّحَى وَتَقُولُ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي إِلَّا أَرْبَعَ رَكَعَاتٍ ‏","","",""],[23603,23603,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَشْعَثُ بْنُ أَبِي الشَّعْثَاءِ الْمُحَارِبِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الِالْتِفَاتِ فِي الصَّلَاةِ فَقَالَ ‏ ‏اخْتِلَاسٌ ‏ ‏يَخْتَلِسُهُ ‏ ‏الشَّيْطَانُ مِنْ صَلَاةِ الْعَبْدِ ‏","","",""],[23604,23604,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏السُّدِّيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي الْمَسْجِدِ فَقَالَ ‏ ‏لِلْجَارِيَةِ ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏قَالَتْ أَرَادَ أَنْ يَبْسُطَهَا فَيُصَلِّيَ عَلَيْهَا قَالَتْ إِنَّهَا حَائِضٌ قَالَ إِنَّ حَيْضَهَا لَيْسَ فِي يَدِهَا ‏","","",""],[23605,23605,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَحَرَّى ‏ ‏صَوْمَ يَوْمِ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسِ ‏","","",""],[23606,23606,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِعَائِشَةَ ‏ ‏مَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ فِي بَيْتِهِ قَالَتْ كَمَا يَصْنَعُ أَحَدُكُمْ يَخْصِفُ نَعْلَهُ وَيُرَقِّعُ ثَوْبَهُ ‏","","",""],[23607,23607,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏قَالَ ‏ ‏سَالِمٌ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كُنْتُ ‏ ‏أُطَيِّبُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَمَا يَرْمِي الْجَمْرَةَ قَبْلَ أَنْ ‏ ‏يُفِيضَ ‏ ‏إِلَى ‏ ‏الْبَيْتِ ‏ ‏قَالَ ‏ ‏سَالِمٌ ‏ ‏فَسُنَّةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَقُّ أَنْ نَأْخُذَ بِهَا مِنْ قَوْلِ ‏ ‏عُمَرَ ‏","","",""],[23608,23608,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏نَافِعٌ يَعْنِي ابْنَ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا كَانَ وَجَعُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي قُبِضَ فِيهِ قَالَ ‏ ‏ادْعُوا لِي ‏ ‏أَبَا بَكْرٍ ‏ ‏وَابْنَهُ فَلْيَكْتُبْ لِكَيْلَا يَطْمَعَ فِي أَمْرِ ‏ ‏أَبِي بَكْرٍ ‏ ‏طَامِعٌ وَلَا يَتَمَنَّى مُتَمَنٍّ ثُمَّ قَالَ ‏ ‏يَأْبَى اللَّهُ ذَلِكَ وَالْمُسْلِمُونَ مَرَّتَيْنِ ‏ ‏و قَالَ ‏ ‏مُؤَمَّلٌ ‏ ‏مَرَّةً وَالْمُؤْمِنُونَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَأَبَى اللَّهُ وَالْمُسْلِمُونَ ‏ ‏و قَالَ ‏ ‏مُؤَمَّلٌ ‏ ‏مَرَّةً ‏ ‏وَالْمُؤْمِنُونَ إِلَّا أَنْ يَكُونَ أَبِي فَكَانَ أَبِي ‏","","",""],[23609,23609,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏شَكَوْا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَجِدُونَ مِنْ الْوَسْوَسَةِ وَقَالُوا يَا رَسُولَ اللَّهِ ‏ ‏إِنَّا لَنَجِدُ شَيْئًا لَوْ أَنَّ أَحَدَنَا ‏ ‏خَرَّ ‏ ‏مِنْ السَّمَاءِ كَانَ أَحَبَّ إِلَيْهِ مِنْ أَنْ يَتَكَلَّمَ بِهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاكَ ‏ ‏مَحْضُ ‏ ‏الْإِيمَانِ ‏","","",""],[23610,23610,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ امْرَأَةُ ‏ ‏عُثْمَانَ بْنِ مَظْعُونٍ ‏ ‏تَخْتَضِبُ وَتَتَطَيَّبُ فَتَرَكَتْهُ فَدَخَلَتْ عَلَيَّ فَقُلْتُ لَهَا أَمُشْهِدٌ أَمْ مُغِيبٌ فَقَالَتْ مُشْهِدٌ كَمُغِيبٍ قُلْتُ لَهَا مَا لَكِ قَالَتْ ‏ ‏عُثْمَانُ ‏ ‏لَا يُرِيدُ الدُّنْيَا وَلَا يُرِيدُ النِّسَاءَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ بِذَلِكَ فَلَقِيَ ‏ ‏عُثْمَانَ ‏ ‏فَقَالَ يَا ‏ ‏عُثْمَانُ ‏ ‏أَتُؤْمِنُ بِمَا نُؤْمِنُ بِهِ قَالَ نَعَمْ يَا رَسُولَ اللَّهِ قَالَ فَأُسْوَةٌ مَا لَكَ بِنَا ‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي فَاخِتَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏بِمِثْلِهِ وَزَادَ فِيهِ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعُثْمَانَ ‏ ‏أَتُؤْمِنُ بِمَا نُؤْمِنُ بِهِ قَالَ نَعَمْ يَا رَسُولَ اللَّهِ قَالَ فَاصْنَعْ كَمَا نَصْنَعُ ‏","","",""],[23611,23611,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَذَكَرَ رَجُلًا آخَرَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصِيبُ مِنْ أَهْلِهِ مِنْ أَوَّلِ اللَّيْلِ ثُمَّ يَنَامُ وَلَا يَمَسُّ مَاءً فَإِذَا اسْتَيْقَظَ مِنْ آخِرِ اللَّيْلِ عَادَ إِلَى أَهْلِهِ وَاغْتَسَلَ ‏","","",""],[23612,23612,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ كُلُّ نِسَائِكَ لَهَا كُنْيَةٌ غَيْرِي قَالَ ‏ ‏فَتَكَنَّيْ بِابْنِكِ ‏ ‏عَبْدِ اللَّهِ ‏","","",""],[23613,23613,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ حَتَّى نَقُولَ لَا يُفْطِرُ وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ وَمَا اسْتَكْمَلَ صِيَامَ شَهْرٍ قَطُّ إِلَّا رَمَضَانَ وَمَا رَأَيْتُهُ فِي شَهْرٍ قَطُّ أَكْثَرَ صِيَامًا مِنْهُ فِي شَعْبَانَ ‏","","",""],[23614,23614,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏أَنَّهَا أَخْبَرَتْهُ أَنَّهَا ‏ ‏سَمِعَتْ ‏ ‏عَائِشَةَ ‏ ‏وَذُكِرَ لَهَا أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ إِنَّ الْمَيِّتَ لَيُعَذَّبُ بِبُكَاءِ الْحَيِّ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَغْفِرُ اللَّهُ ‏ ‏لِأَبِي عَبْدِ الرَّحْمَنِ ‏ ‏أَمَا إِنَّهُ لَمْ يَكْذِبْ وَلَكِنَّهُ نَسِيَ أَوْ أَخْطَأَ إِنَّمَا مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى يَهُودِيَّةٍ ‏ ‏يُبْكَى عَلَيْهَا فَقَالَ ‏ ‏إِنَّهُمْ لَيَبْكُونَ عَلَيْهَا وَإِنَّهَا لَتُعَذَّبُ فِي قَبْرِهَا ‏","","",""],[23615,23615,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مِنْ كُلِّ اللَّيْلِ قَدْ ‏ ‏أَوْتَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَوَّلِهِ وَأَوْسَطِهِ وَآخِرِهِ فَانْتَهَى ‏ ‏وِتْرُهُ ‏ ‏إِلَى ‏ ‏السَّحَرِ ‏","","",""],[23616,23616,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْمُنْكَدِرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْرَدَ الْحَجَّ ‏","","",""],[23617,23617,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏طَيَّبْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏قَبْلَ أَنْ يَزُورَ ‏ ‏الْبَيْتَ ‏","","",""],[23618,23618,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ وَإِنَّهُ لَمَكْتُوبٌ فِي الْكِتَابِ مِنْ أَهْلِ النَّارِ فَإِذَا كَانَ قَبْلَ مَوْتِهِ تَحَوَّلَ فَعَمِلَ بِعَمَلِ أَهْلِ النَّارِ فَمَاتَ فَدَخَلَ النَّارَ وَإِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ وَإِنَّهُ لَمَكْتُوبٌ فِي الْكِتَابِ مِنْ أَهْلِ الْجَنَّةِ فَإِذَا كَانَ قَبْلَ مَوْتِهِ تَحَوَّلَ فَعَمِلَ بِعَمَلِ أَهْلِ الْجَنَّةِ فَمَاتَ فَدَخَلَهَا ‏","","",""],[23619,23619,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَعَنْ ‏ ‏عَلْقَمَةَ بْنِ أَبِي عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَعَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْرَدَ الْحَجَّ ‏","","",""],[23620,23620,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّ ‏ ‏أَمْدَادَ ‏ ‏الْعَرَبِ ‏ ‏كَثُرُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى غَمُّوهُ وَقَامَ إِلَيْهِ ‏ ‏الْمُهَاجِرُونَ ‏ ‏يَفْرِجُونَ دُونَهُ حَتَّى قَامَ عَلَى عَتَبَةِ ‏ ‏عَائِشَةَ ‏ ‏فَرَهِقُوهُ فَأَسْلَمَ رِدَاءَهُ فِي أَيْدِيهِمْ ‏ ‏وَوَثَبَ ‏ ‏عَلَى الْعَتَبَةِ فَدَخَلَ وَقَالَ اللَّهُمَّ الْعَنْهُمْ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ هَلَكَ الْقَوْمُ فَقَالَ كَلَّا وَاللَّهِ يَا ‏ ‏بِنْتَ أَبِي بَكْرٍ ‏ ‏لَقَدْ اشْتَرَطْتُ عَلَى رَبِّي عَزَّ وَجَلَّ شَرْطًا لَا خُلْفَ لَهُ فَقُلْتُ إِنَّمَا ‏ ‏أَنَا بَشَرٌ أَضِيقُ ‏ ‏بِمَا ‏ ‏يَضِيقُ بِهِ الْبَشَرُ فَأَيُّ الْمُؤْمِنِينَ بَدَرَتْ إِلَيْهِ مِنِّي بَادِرَةٌ فَاجْعَلْهَا لَهُ كَفَّارَةً ‏","","",""],[23621,23621,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ يَوْمٍ إِلَّا وَهُوَ ‏ ‏يَطُوفُ ‏ ‏عَلَيْنَا جَمِيعًا امْرَأَةً امْرَأَةً فَيَدْنُو وَيَلْمِسُ مِنْ غَيْرِ مَسِيسٍ حَتَّى يُفْضِيَ إِلَى الَّتِي هُوَ يَوْمُهَا فَيَبِيتَ عِنْدَهَا ‏","","",""],[23622,23622,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏يَا ابْنَ أُخْتِي قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَائِشَةُ ‏ ‏لَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصِيَ ‏ ‏اللَّهُ عَلَيْكِ ‏","","",""],[23623,23623,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏يَا ابْنَ أُخْتِي قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏إِنَّ الرَّجُلَ لَيَعْمَلُ الزَّمَانَ بِعَمَلِ أَهْلِ النَّارِ وَإِنَّهُ عِنْدَ اللَّهِ عَزَّ وَجَلَّ لَمَكْتُوبٌ مِنْ أَهْلِ الْجَنَّةِ وَإِنَّ الرَّجُلَ لَيَعْمَلُ الزَّمَانَ بِعَمَلِ أَهْلِ الْجَنَّةِ وَإِنَّهُ عِنْدَ اللَّهِ عَزَّ وَجَلَّ لَمَكْتُوبٌ مِنْ أَهْلِ النَّارِ ‏","","",""],[23624,23624,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏يَا ابْنَ أُخْتِي كَانَ ‏ ‏شَعْرُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوْقَ ‏ ‏الْوَفْرَةِ ‏ ‏وَدُونَ ‏ ‏الْجُمَّةِ ‏ ‏وَايْمُ اللَّهِ يَا ابْنَ أُخْتِي إِنْ كَانَ لَيَمُرُّ عَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ مَا يُوقَدُ فِي بَيْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ نَارٍ إِلَّا أَنْ يَكُونَ ‏ ‏اللُّحَيْمُ ‏ ‏وَمَا هُوَ إِلَّا ‏ ‏الْأَسْوَدَانِ ‏ ‏الْمَاءُ وَالتَّمْرُ إِلَّا أَنَّ حَوْلَنَا أَهْلَ دُورٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏جَزَاهُمْ اللَّهُ خَيْرًا فِي الْحَدِيثِ وَالْقَدِيمِ فَكُلُّ يَوْمٍ يَبْعَثُونَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِغَزِيرَةِ شَاتِهِمْ ‏ ‏يَعْنِي فَيَنَالُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ذَلِكَ اللَّبَنِ ‏ ‏وَلَقَدْ تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا فِي رَفِّي مِنْ طَعَامٍ يَأْكُلُهُ ذُو كَبِدٍ إِلَّا قَرِيبٌ مِنْ شَطْرِ شَعِيرٍ فَأَكَلْتُ مِنْهُ حَتَّى طَالَ عَلَيَّ لَا ‏ ‏يَفْنَى فَكِلْتُهُ فَفَنِيَ فَلَيْتَنِي لَمْ أَكُنْ كِلْتُهُ وَايْمُ اللَّهِ لَأَنْ كَانَ ضِجَاعُهُ مِنْ ‏ ‏أَدَمٍ ‏ ‏حَشْوُهُ لِيفٌ ‏ ‏و قَالَ ‏ ‏الْهَاشِمِيُّ ‏ ‏بِغَزِيرَةِ شَاتِهِمْ وَذَكَرَ نَحْوَهُ إِلَّا ضِجَاعُهُ ‏","","",""],[23625,23625,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ نُوقِشَ الْمُحَاسَبَةَ لَمْ يُغْفَرْ لَهُ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ فَأَيْنَ قَوْلُهُ ‏ { ‏يُحَاسَبُ حِسَابًا يَسِيرًا ‏} ‏قَالَ ذَاكَ الْعَرْضُ ‏","","",""],[23626,23626,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏وَمُوسَى بْنُ دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ الدَّرَاوَرْدِيُّ ‏ ‏قَالَ ‏ ‏مُوسَى ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُسْتَقَى لَهُ الْمَاءُ مِنْ بُيُوتِ السُّقْيَا ‏","","",""],[23627,23627,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ قُرْظٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ذَهَبَ أَحَدُكُمْ لِحَاجَتِهِ ‏ ‏فَلْيَسْتَطِبْ ‏ ‏بِثَلَاثَةِ أَحْجَارٍ فَإِنَّهَا تُجْزِئُهُ ‏","","",""],[23628,23628,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حُوسِبَ عُذِّبَ ‏","","",""],[23629,23629,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏تَصَدَّقَتْ بِشَيْءٍ فَأَمَرَتْ ‏ ‏بَرِيرَةَ ‏ ‏أَنْ تَأْتِيَهَا فَتَنْظُرَ إِلَيْهِ فَقَالَ لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُحْصِي ‏ ‏فَيُحْصَى ‏ ‏عَلَيْكِ ‏","","",""],[23630,23630,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏مَرِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَضَعْتُ يَدِي عَلَى صَدْرِهِ فَقُلْتُ ‏ ‏أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ أَنْتَ الطَّبِيبُ وَأَنْتَ الشَّافِي وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ أَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى ‏","","",""],[23631,23631,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا غَلَبَتْهُ عَيْنُهُ أَوْ وَجِعَ فَلَمْ يُصَلِّ بِاللَّيْلِ صَلَّى بِالنَّهَارِ اثْنَتَيْ عَشْرَةَ رَكْعَةً ‏","","",""],[23632,23632,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا ‏ ‏عَادَ ‏ ‏مَرِيضًا قَالَ ‏ ‏أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ وَاشْفِ إِنَّكَ أَنْتَ الشَّافِي وَلَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا ‏ ‏يُغَادِرُ ‏ ‏سَقَمًا ‏","","",""],[23633,23633,"","","‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا مَرِضَ أَوْ نَامَ صَلَّى بِالنَّهَارِ اثْنَتَيْ عَشْرَةَ رَكْعَةً قَالَتْ وَمَا رَأَيْتُهُ قَامَ لَيْلَةً إِلَى الصُّبْحِ وَلَا صَامَ شَهْرًا تَامًّا مُتَتَابِعًا إِلَّا رَمَضَانَ وَقَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْمَلُ عَمَلًا يُثْبِتُهُ ‏","","",""],[23634,23634,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَتْ لَهُ حَاجَةٌ إِلَى أَهْلِهِ أَتَاهُمْ ثُمَّ يَعُودُ وَلَا يَمَسُّ مَاءً ‏","","",""],[23635,23635,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُ أَوَّلَ اللَّيْلِ وَيَقُومُ آخِرَهُ ‏","","",""],[23636,23636,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏سَائِبَةَ ‏ ‏مَوْلَاةٍ ‏ ‏لِلْفَاكِهِ بْنِ الْمُغِيرَةِ ‏ ‏أَنَّهَا دَخَلَتْ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَرَأَتْ فِي بَيْتِهَا رُمْحًا مَوْضُوعًا فَقَالَتْ يَا أُمَّ الْمُؤْمِنِينَ مَا تَصْنَعِينَ بِهَذَا الرُّمْحِ قَالَتْ نَقْتُلُ بِهِ ‏ ‏الْأَوْزَاغَ ‏ ‏فَإِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَنَا ‏ ‏أَنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏حِينَ أُلْقِيَ فِي النَّارِ لَمْ تَكُنْ دَابَّةٌ إِلَّا تُطْفِئُ النَّارَ عَنْهُ غَيْرُ ‏ ‏الْوَزَغِ ‏ ‏فَإِنَّهُ كَانَ يَنْفُخُ عَلَيْهِ فَأَمَرَ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏بِقَتْلِهِ ‏","","",""],[23637,23637,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏وَعَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏لَكَأَنِّي ‏ ‏أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الطِّيبِ فِي مَفَارِقِهِ وَهُوَ ‏ ‏يُلَبِّي ‏ ‏قَيْلَ ‏ ‏لِسُلَيْمَانَ ‏ ‏أَفِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏","","",""],[23638,23638,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَأَنِّي ‏ ‏أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الطِّيبِ فِي مَفْرِقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23639,23639,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏أُمِّ مُوسَى ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ فَقَالَتْ مَا أَتَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي يَوْمٍ إِلَّا ‏ ‏صَلَّى بَعْدَ الْعَصْرِ رَكْعَتَيْنِ ‏","","",""],[23640,23640,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عُبَيْدِ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ شَرُّ الثَّلَاثَةِ إِذَا عَمِلَ بِعَمَلِ أَبَوَيْهِ ‏ ‏يَعْنِي وَلَدَ الزِّنَا ‏","","",""],[23641,23641,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَتْلِ الْكِلَابِ الْعِينِ ‏","","",""],[23642,23642,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏مَا كَانَ يَصْنَعُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ أَنْ يَخْرُجَ قَالَتْ كَانَ ‏ ‏يُصَلِّي الرَّكْعَتَيْنِ ثُمَّ يَخْرُجُ ‏","","",""],[23643,23643,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَهْدَى إِلَى ‏ ‏الْبَيْتِ ‏ ‏غَنَمًا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23644,23644,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زُرَارَةَ بْنَ أَوْفَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الَّذِي يَقْرَأُ الْقُرْآنَ وَيَتَعَاهَدُهُ وَهُوَ عَلَيْهِ شَدِيدٌ فَلَهُ أَجْرَانِ قَالَ وَمَثَلُ الَّذِي يَقْرَأُ الْقُرْآنَ وَهُوَ حَافِظٌ مَثَلُ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ ‏","","",""],[23645,23645,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ فَقَالَتْ كَانَ ‏ ‏إِذَا سَمِعَ الصَّارِخَ قَامَ فَصَلَّى ‏","","",""],[23646,23646,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هُرَيْمٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏تُوُفِّيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الِاثْنَيْنِ وَدُفِنَ لَيْلَةَ الْأَرْبِعَاءِ ‏","","",""],[23647,23647,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏بُدَيْلِ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْجَوْزَاءِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَسْتَفْتِحُ الْقِرَاءَةَ بِ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏}","","",""],[23648,23648,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏أُمِّ كُلْثُومٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏فَعَلْنَاهُ مَرَّةً ‏ ‏فَاغْتَسَلْنَا ‏ ‏فِي الَّذِي يُجَامِعُ وَلَا يُنْزِلُ ‏","","",""],[23649,23649,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏هَلْ يَذْكُرُ الْحَبِيبُ حَبِيبَهُ يَوْمَ الْقِيَامَةِ قَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏أَمَّا عِنْدَ ثَلَاثٍ فَلَا أَمَّا عِنْدَ الْمِيزَانِ حَتَّى يَثْقُلَ أَوْ يَخِفَّ فَلَا وَأَمَّا عِنْدَ تَطَايُرِ الْكُتُبِ فَإِمَّا أَنْ يُعْطَى بِيَمِينِهِ أَوْ يُعْطَى بِشِمَالِهِ فَلَا وَحِينَ يَخْرُجُ عُنُقٌ مِنْ النَّارِ ‏ ‏فَيَنْطَوِي عَلَيْهِمْ وَيَتَغَيَّظُ عَلَيْهِمْ وَيَقُولُ ذَلِكَ الْعُنُقُ وُكِّلْتُ بِثَلَاثَةٍ وُكِّلْتُ بِثَلَاثَةٍ وُكِّلْتُ بِمَنْ ادَّعَى مَعَ اللَّهِ إِلَهًا آخَرَ وَوُكِّلْتُ بِمَنْ لَا يُؤْمِنُ بِيَوْمِ الْحِسَابِ وَوُكِّلْتُ بِكُلِّ جَبَّارٍ عَنِيدٍ قَالَ ‏ ‏فَيَنْطَوِي عَلَيْهِمْ ‏ ‏وَيَرْمِي بِهِمْ فِي ‏ ‏غَمَرَاتٍ ‏ ‏وَلِجَهَنَّمَ جِسْرٌ أَدَقُّ مِنْ الشَّعْرِ وَأَحَدُّ مِنْ السَّيْفِ عَلَيْهِ ‏ ‏كَلَالِيبُ ‏ ‏وَحَسَكٌ ‏ ‏يَأْخُذُونَ مَنْ شَاءَ اللَّهُ وَالنَّاسُ عَلَيْهِ ‏ ‏كَالطَّرْفِ ‏ ‏وَكَالْبَرْقِ وَكَالرِّيحِ ‏ ‏وَكَأَجَاوِيدِ ‏ ‏الْخَيْلِ ‏ ‏وَالرِّكَابِ ‏ ‏وَالْمَلَائِكَةُ يَقُولُونَ رَبِّ سَلِّمْ رَبِّ سَلِّمْ فَنَاجٍ مُسَلَّمٌ وَمَخْدُوشٌ مُسَلَّمٌ وَمُكَوَّرٌ فِي النَّارِ عَلَى وَجْهِهِ ‏","","",""],[23650,23650,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْعَبَّاسِ بْنِ ذَرِيحٍ ‏ ‏عَنْ ‏ ‏الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏فَقَالَتْ إِنِّي حَائِضٌ فَقَالَ إِنَّهَا لَيْسَتْ فِي يَدِكِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَدْ ‏ ‏حَدَّثَنَا ‏ ‏بِهِ ‏ ‏وَكِيعٌ ‏","","",""],[23651,23651,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ ‏ ‏أَوَّلُ مَا يَبْدَأُ بِهِ إِذَا دَخَلَ بَيْتَهُ السِّوَاكَ وَآخِرُهُ إِذَا خَرَجَ مِنْ بَيْتِهِ الرَّكْعَتَيْنِ قَبْلَ الْفَجْرِ ‏","","",""],[23652,23652,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏وَحَجَّاجٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَتْ ائْتِ ‏ ‏عَلِيًّا ‏ ‏فَاسْأَلْهُ قَالَ فَأَتَيْتُهُ فَقَالَ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُنَا إِذَا سَافَرْنَا أَنْ نَمْسَحَ عَلَى خِفَافِنَا ‏ ‏قَالَ ‏ ‏أَسْوَدُ ‏ ‏فِي حَدِيثِهِ وَرُبَّمَا ‏ ‏قَالَ ‏ ‏شَرِيكٌ ‏ ‏كُنَّا إِذَا كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ مَسَحْنَا عَلَى خِفَافِنَا ‏","","",""],[23653,23653,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مُنْذُ سِتِّينَ سَنَةً ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَجْمَرْتُ رَأْسِي إِجْمَارًا شَدِيدًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَائِشَةُ ‏ ‏أَمَا عَلِمْتِ أَنَّ عَلَى كُلِّ شَعَرَةٍ جَنَابَةً ‏","","",""],[23654,23654,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَجُلًا دَخَلَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَدْنَاهُ وَقَرَّبَ مَجْلِسَهُ فَلَمَّا خَرَجَ قَالَتْ لَهُ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ أَلَمْ تَكُ تَشْكُو هَذَا الرَّجُلَ قَالَ بَلَى وَلَكِنْ ‏ ‏إِنَّ مِنْ شِرَارِ النَّاسِ ‏ ‏أَوْ شَرِّ النَّاسِ ‏ ‏الَّذِينَ إِنَّمَا يُكْرَمُونَ اتِّقَاءَ شَرِّهِمْ ‏","","",""],[23655,23655,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُجْنِبُ ثُمَّ يَنَامُ ثُمَّ يَنْتَبِهُ ثُمَّ يَنَامُ وَلَا يَمَسُّ مَاءً ‏","","",""],[23656,23656,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي سُوَاءَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ خُلُقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ أَمَا تَقْرَأُ الْقُرْآنَ ‏ { ‏إِنَّكَ لَعَلَى خُلُقٍ عَظِيمٍ ‏} ‏قَالَ قُلْتُ حَدِّثِينِي عَنْ ذَاكَ قَالَتْ صَنَعْتُ لَهُ طَعَامًا وَصَنَعَتْ لَهُ ‏ ‏حَفْصَةُ ‏ ‏طَعَامًا فَقُلْتُ لِجَارِيَتِي اذْهَبِي فَإِنْ جَاءَتْ هِيَ بِالطَّعَامِ فَوَضَعَتْهُ قَبْلُ فَاطْرَحِي الطَّعَامَ قَالَتْ فَجَاءَتْ بِالطَّعَامِ قَالَتْ فَأَلْقَتْهُ الْجَارِيَةُ فَوَقَعَتْ ‏ ‏الْقَصْعَةُ ‏ ‏فَانْكَسَرَتْ وَكَانَ ‏ ‏نِطْعًا ‏ ‏قَالَتْ فَجَمَعَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏اقْتَصُّوا ‏ ‏أَوْ ‏ ‏اقْتَصِّي ‏ ‏شَكَّ ‏ ‏أَسْوَدُ ‏ ‏ظَرْفًا ‏ ‏مَكَانَ ‏ ‏ظَرْفِكِ ‏ ‏فَمَا قَالَ شَيْءٌ ‏","","",""],[23657,23657,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ فِرَاشِهِ فِي بَعْضِ اللَّيْلِ فَظَنَنْتُ أَنَّهُ يُرِيدُ بَعْضَ نِسَائِهِ فَتَبِعْتُهُ حَتَّى قَامَ عَلَى الْمَقَابِرِ فَقَالَ ‏ ‏السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ وَإِنَّا بِكُمْ لَاحِقُونَ ثُمَّ قَالَ اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُمْ وَلَا تَفْتِنَّا بَعْدَهُمْ قَالَتْ فَالْتَفَتَ فَرَآنِي فَقَالَ وَيْحَهَا لَوْ تَسْتَطِيعُ مَا فَعَلَتْ ‏","","",""],[23658,23658,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏شَكَّ ‏ ‏شَرِيكٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجَدَ عَلَى ‏ ‏الْخُمْرَةِ ‏","","",""],[23659,23659,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ امْرَأَةً أَتَتْهَا فَقَالَتْ إِنَّ ابْنَتِي عَرُوسٌ مَرِضَتْ ‏ ‏فَتَمَرَّقَ ‏ ‏شَعَرُهَا أَفَأَصِلُ فِيهِ فَقَالَتْ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏ ‏أَوْ قَالَتْ ‏ ‏الْوَاصِلَةَ ‏","","",""],[23660,23660,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏امْرَأَتِهِ ‏ ‏فَاطِمَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ ابْنَةِ أَبِي بَكْرٍ ‏ ‏أَنَّ امْرَأَةً أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ إِنَّ لِي ابْنَةً عَرُوسًا وَإِنَّهَا مَرِضَتْ ‏ ‏فَتَمَرَّقَ ‏ ‏شَعَرُهَا أَفَأَصِلُهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏","","",""],[23661,23661,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ بْنُ الْحَجَّاجِ الْعَتَكِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ بْنَ مُسْلِمِ بْنِ يَنَّاقٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ جَارِيَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏زُوِّجَتْ وَأَنَّهَا مَرِضَتْ ‏ ‏فَتَمَعَّطَ ‏ ‏شَعَرُهَا فَأَرَادُوا أَنْ ‏ ‏يَصِلُوهُ ‏ ‏فَسَأَلُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْوِصَالِ ‏ ‏فَلَعَنَ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏","","",""],[23662,23662,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏وَأَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلُ مِنْ الْجَنَابَةِ ثُمَّ يَأْتِي الْمَسْجِدَ وَرَأْسُهُ يَقْطُرُ وَهُوَ يُرِيدُ الصَّوْمَ ذَلِكَ الْيَوْمَ ‏","","",""],[23663,23663,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏وَأَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏مِنْ الْمَسْجِدِ قَالَتْ قُلْتُ إِنِّي حَائِضٌ قَالَ إِنَّ حَيْضَكِ لَيْسَ بِيَدِكِ ‏ ‏قَالَ ‏ ‏أَبُو أَحْمَدَ ‏ ‏إِنَّ حَيْضَتَكِ لَيْسَتْ مِنْ يَدِكِ ‏","","",""],[23664,23664,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْبَادِيَةِ ‏ ‏إِلَى إِبِلِ الصَّدَقَةِ فَأَعْطَى نِسَاءَهُ بَعِيرًا بَعِيرًا غَيْرِي فَقُلْتُ يَا رَسُولَ اللَّهِ أَعْطَيْتَهُنَّ بَعِيرًا بَعِيرًا غَيْرِي فَأَعْطَانِي بَعِيرًا ‏ ‏آدَدَ ‏ ‏صَعْبًا لَمْ يُرْكَبْ عَلَيْهِ فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏ارْفُقِي بِهِ فَإِنَّ الرِّفْقَ لَا يُخَالِطُ شَيْئًا إِلَّا زَانَهُ وَلَا يُفَارِقُ شَيْئًا إِلَّا ‏ ‏شَانَهُ ‏","","",""],[23665,23665,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى قَائِمًا رَكَعَ قَائِمًا وَإِذَا صَلَّى قَاعِدًا رَكَعَ قَاعِدًا ‏","","",""],[23666,23666,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ يَا أُمَّ الْمُؤْمِنِينَ ‏ ‏إِنِّي أُرِيدُ أَنْ أَتَبَتَّلَ فَقَالَتْ لَا تَفْعَلْ أَلَمْ تَقْرَأْ ‏ { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏} ‏قَدْ تَزَوَّجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَوُلِدَ لَهُ ‏","","",""],[23667,23667,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الرِّجَالِ مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يُمْنَعُ ‏ ‏نَقْعُ ‏ ‏مَاءٍ وَلَا رَهْوُ بِئْرٍ ‏","","",""],[23668,23668,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا اشْتَرَتْ ‏ ‏نَمَطًا ‏ ‏فِيهِ ‏ ‏تَصَاوِيرُ ‏ ‏فَأَرَادَتْ أَنْ تَصْنَعَهُ ‏ ‏حَجَلَةً ‏ ‏فَدَخَلَ عَلَيْهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرَتْهُ إِيَّاهُ وَأَخْبَرَتْهُ أَنَّهَا تُرِيدُ أَنْ تَصْنَعَهُ ‏ ‏حَجَلَةً ‏ ‏فَقَالَ لَهَا ‏ ‏اقْطَعِيهِ وِسَادَتَيْنِ قَالَتْ فَفَعَلْتُ فَكُنْتُ أَتَوَسَّدُهُمَا وَيَتَوَسَّدُهُمَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23669,23669,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ بَشِيرٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ سَبَلَانَ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ ‏ ‏عَائِشَةَ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏قَالَ وَكَانَتْ تَخْرُجُ ‏ ‏بِأَبِي يَحْيَى التَّيْمِيِّ ‏ ‏يُصَلِّي بِهَا قَالَ فَأَدْرَكَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏فَأَسَاءَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏الْوُضُوءَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏أَسْبِغْ ‏ ‏الْوُضُوءَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏يَوْمَ الْقِيَامَةِ مِنْ النَّارِ ‏","","",""],[23670,23670,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ قَرْمٍ ‏ ‏عَنْ ‏ ‏الْأَشْعَثِ يَعْنِي ابْنَ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏حَبَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نَنْتَبِذَ ‏ ‏فِي ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[23671,23671,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَامِرًا ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏إِنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يُقْرِئُكِ السَّلَامَ فَقَالَتْ وَعَلَيْهِ السَّلَامُ وَرَحْمَةُ اللَّهِ ‏","","",""],[23672,23672,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْتِيهِ ‏ ‏بِلَالٌ ‏ ‏فَيُؤْذِنُهُ لِلصَّلَاةِ وَهُوَ جُنُبٌ فَيَقُومُ ‏ ‏فَيَغْتَسِلُ ثُمَّ يَأْتِي الْمَسْجِدَ فَيُصَلِّي وَأَنَا أَسْمَعُ قِرَاءَتَهُ وَرَأْسُهُ يَقْطُرُ ثُمَّ يَصُومُ ذَلِكَ الْيَوْمَ ‏","","",""],[23673,23673,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَلَسَ بَيْنَ ‏ ‏الشُّعَبِ ‏ ‏الْأَرْبَعِ ثُمَّ أَلْزَقَ الْخِتَانَ بِالْخِتَانِ فَقَدْ وَجَبَ الْغُسْلُ ‏","","",""],[23674,23674,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَانَ لِآلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحْشٌ فَإِذَا خَرَجَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعِبَ وَاشْتَدَّ وَأَقْبَلَ وَأَدْبَرَ فَإِذَا أَحَسَّ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ دَخَلَ ‏ ‏رَبَضَ ‏ ‏فَلَمْ ‏ ‏يَتَرَمْرَمْ ‏ ‏مَا دَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْبَيْتِ كَرَاهِيَةَ أَنْ يُؤْذِيَهُ ‏","","",""],[23675,23675,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏حَدِّثِينِي بِأَحَبِّ الْعَمَلِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ كَانَ ‏ ‏أَحَبُّ الْعَمَلِ إِلَيْهِ الَّذِي يَدُومُ عَلَيْهِ الرَّجُلُ وَإِنْ كَانَ يَسِيرًا ‏","","",""],[23676,23676,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ حَبِيبٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ ‏ ‏فَوَقَعَ ‏ ‏فِي ‏ ‏عَلِيٍّ ‏ ‏وَفِي ‏ ‏عَمَّارٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏عِنْدَ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ أَمَّا ‏ ‏عَلِيٌّ ‏ ‏فَلَسْتُ قَائِلَةً لَكَ فِيهِ شَيْئًا وَأَمَّا ‏ ‏عَمَّارٌ ‏ ‏فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يُخَيَّرُ بَيْنَ أَمْرَيْنِ إِلَّا اخْتَارَ أَرْشَدَهُمَا ‏","","",""],[23677,23677,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورِ ابْنِ صَفِيَّةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَوْلَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَعْضِ نِسَائِهِ ‏ ‏بِمُدَّيْنِ ‏ ‏مِنْ شَعِيرٍ ‏","","",""],[23678,23678,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الزُّبَيْرِيُّ ‏ ‏مَوْلَى ‏ ‏بَنِي أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي لَيْلًا طَوِيلًا قَائِمًا وَلَيْلًا طَوِيلًا جَالِسًا قُلْتُ فَكَيْفَ كَانَ يَصْنَعُ قَالَتْ كَانَ إِذَا قَرَأَ قَائِمًا رَكَعَ قَائِمًا وَإِذَا قَرَأَ جَالِسًا رَكَعَ جَالِسًا ‏","","",""],[23679,23679,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏وَمَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَشْهَدُ أَنَّهُ ‏ ‏لَمْ يَأْتِ فِي يَوْمِي قَطُّ إِلَّا صَلَّى بَعْدَ الْعَصْرِ رَكْعَتَيْنِ ‏","","",""],[23680,23680,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَاشِرُنِي وَأَنَا حَائِضٌ وَيَدْخُلُ مَعِي فِي لِحَافِي وَأَنَا حَائِضٌ وَلَكِنَّهُ كَانَ أَمْلَكَكُمْ ‏ ‏لِإِرْبِهِ ‏","","",""],[23681,23681,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِيسَى بْنُ عَبْدِ الرَّحْمَنِ الْبَجَلِيُّ السُّلَمِيُّ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الْعُمْرَةِ بَعْدَ الْحَجِّ قَالَتْ ‏ ‏أَرْسَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعِي ‏ ‏أَخِي ‏ ‏فَخَرَجْتُ مِنْ ‏ ‏الْحَرَمِ ‏ ‏فَاعْتَمَرْتُ ‏","","",""],[23682,23682,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَيَزِيدَ الرِّشْكِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مُرْنَ أَزْوَاجَكُنَّ أَنْ يَغْسِلُوا عَنْهُمْ أَثَرَ ‏ ‏الْغَائِطِ ‏ ‏وَالْبَوْلِ فَإِنَّا ‏ ‏نَسْتَحْيِي مِنْهُمْ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُ ذَلِكَ ‏","","",""],[23683,23683,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مُحَمَّدِ بْنِ أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏أَخْبَرَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَمْ تَرَيْ إِلَى قَوْمِكِ حِينَ بَنَوْا ‏ ‏الْكَعْبَةَ ‏ ‏اقْتَصَرُوا ‏ ‏عَنْ قَوَاعِدِ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ أَفَلَا تَرُدُّهَا عَلَى قَوَاعِدِ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا حِدْثَانُ قَوْمِكِ بِالْكُفْرِ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏فَوَاللَّهِ لَئِنْ كَانَتْ ‏ ‏عَائِشَةُ ‏ ‏سَمِعَتْ ذَلِكَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أُرَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَرَكَ ‏ ‏اسْتِلَامَ ‏ ‏الرُّكْنَيْنِ اللَّذَيْنِ يَلِيَانِ الْحَجَرَ إِلَّا أَنَّ ‏ ‏الْبَيْتَ ‏ ‏لَمْ يُتَمَّمْ عَلَى قَوَاعِدِ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏إِرَادَةَ أَنْ تَسْتَوْعِبَ النَّاسُ الطَّوَافَ ‏ ‏بِالْبَيْتِ ‏ ‏كُلِّهِ مِنْ وَرَاءِ قَوَاعِدِ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[23684,23684,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏كَانَتْ ‏ ‏تَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُصِيبَةٍ يُصَابُ بِهَا الْمُسْلِمُ إِلَّا كُفِّرَ بِهَا عَنْهُ حَتَّى الشَّوْكَةِ يُشَاكُهَا ‏","","",""],[23685,23685,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَائِشَةَ أُمَّ الْمُؤْمِنِينَ ‏ ‏حَدَّثَتْهُ ‏ ‏عَنْ بَيْعَةِ النِّسَاءِ ‏ ‏مَا ‏ ‏مَسَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ يَدَ امْرَأَةٍ قَطُّ إِلَّا أَنْ يَأْخُذَ عَلَيْهَا فَإِذَا أَخَذَ عَلَيْهَا فَأَعْطَتْهُ قَالَ اذْهَبِي فَقَدْ ‏ ‏بَايَعْتُكِ ‏","","",""],[23686,23686,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهُ ‏ ‏قَالَتْ ‏ ‏مَا خُيِّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَمْرَيْنِ قَطُّ إِلَّا اخْتَارَ أَيْسَرَهُمَا حَتَّى يَكُونَ إِثْمًا فَإِذَا كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ وَمَا انْتَقَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِنَفْسِهِ مِنْ شَيْءٍ انْتُهِكَ مِنْهُ إِلَّا أَنْ ‏ ‏تُنْتَهَكَ ‏ ‏حُرْمَةٌ هِيَ لِلَّهِ عَزَّ وَجَلَّ فَيَنْتَقِمُ لِلَّهِ عَزَّ وَجَلَّ بِهَا ‏","","",""],[23687,23687,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا ‏ ‏اشْتَكَى ‏ ‏يَقْرَأُ عَلَى نَفْسِهِ ‏ ‏بِالْمُعَوِّذَاتِ ‏ ‏وَيَنْفُثُ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَلَمَّا اشْتَدَّ وَجَعُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُنْتُ أَنَا أَقْرَأُ عَلَيْهِ وَأَمْسَحُ عَنْهُ بِيَدِهِ رَجَاءَ بَرَكَتِهَا ‏","","",""],[23688,23688,"","","‏ ‏حَدَّثَنَا ‏ ‏أُرَاهُ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ حُمَيْدِ بْنِ أَبِي غَنِيَّةَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏مِنْ الْمَسْجِدِ قُلْتُ إِنِّي حَائِضٌ قَالَ إِنَّ حَيْضَتَكِ لَيْسَتْ فِي يَدِكِ ‏","","",""],[23689,23689,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ أَيْمَنَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي كَثِيرًا مِنْ صَلَاتِهِ وَهُوَ جَالِسٌ ‏","","",""],[23690,23690,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ أَيْمَنَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ أَقْرَعَ بَيْنَ نِسَائِهِ ‏","","",""],[23691,23691,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أَهْدَتْ إِلَيْهَا امْرَأَةٌ تَمْرًا فِي طَبَقٍ فَأَكَلَتْ بَعْضًا وَبَقِيَ بَعْضٌ فَقَالَتْ ‏ ‏أَقْسَمْتُ عَلَيْكِ إِلَّا أَكَلْتِ بَقِيَّتَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبِرِّيهَا فَإِنَّ الْإِثْمَ عَلَى الْمُحَنِّثِ ‏","","",""],[23692,23692,"","","‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مُرْنَ أَزْوَاجَكُنَّ أَنْ يَغْسِلُوا عَنْهُمْ أَثَرَ ‏ ‏الْغَائِطِ ‏ ‏وَالْبَوْلِ فَإِنَّا نَسْتَحِي مِنْهُمْ وَإِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُ ذَلِكَ ‏","","",""],[23693,23693,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ كُنَاسَةَ الْأَسَدِيُّ أَبُو يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏بَلَغَنِي ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا اسْتَمَعْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا مَرَّةً فَإِنَّ ‏ ‏عُثْمَانَ ‏ ‏جَاءَهُ فِي ‏ ‏نَحْرِ ‏ ‏الظَّهِيرَةِ فَظَنَنْتُ أَنَّهُ جَاءَهُ فِي أَمْرِ النِّسَاءِ فَحَمَلَتْنِي الْغَيْرَةُ عَلَى أَنْ أَصْغَيْتُ إِلَيْهِ فَسَمِعْتُهُ يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ مُلْبِسُكَ قَمِيصًا تُرِيدُكَ أُمَّتِي عَلَى خَلْعِهِ فَلَا تَخْلَعْهُ فَلَمَّا رَأَيْتُ ‏ ‏عُثْمَانَ ‏ ‏يَبْذُلُ لَهُمْ مَا سَأَلُوهُ إِلَّا خَلْعَهُ عَلِمْتُ أَنَّهُ مِنْ عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي عَهِدَ إِلَيْهِ ‏","","",""],[23694,23694,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَابِقٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ طَهْمَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏وَأَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ بِمَرِيضٍ قَالَ ‏ ‏أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ ‏ ‏اشْفِ أَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا ‏ ‏يُغَادِرُ ‏ ‏سَقَمًا ‏","","",""],[23695,23695,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا اشْتَرَتْ ‏ ‏بَرِيرَةَ ‏ ‏مِنْ نَاسٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَاشْتَرَطُوا ‏ ‏الْوَلَاءَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ ‏ ‏وَلِي ‏ ‏النِّعْمَةَ قَالَ وَخَيَّرَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ زَوْجُهَا عَبْدًا فَأَهْدَتْ إِلَى ‏ ‏عَائِشَةَ ‏ ‏لَحْمًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ صَنَعْتُمْ لَنَا مِنْ هَذَا اللَّحْمِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏تُصُدِّقَ بِهِ عَلَى ‏ ‏بَرِيرَةَ ‏ ‏فَقَالَ هُوَ عَلَيْهَا ‏ ‏صَدَقَةٌ ‏ ‏وَهُوَ لَنَا هَدِيَّةٌ ‏","","",""],[23696,23696,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِلْأَسْوَدِ ‏ ‏هَلْ سَأَلْتَ ‏ ‏أُمَّ الْمُؤْمِنِينَ عَائِشَةَ ‏ ‏عَمَّا يُكْرَهُ أَنْ يُنْتَبَذَ فِيهِ فَقَالَ نَعَمْ قُلْتُ لَهَا يَا أُمَّ الْمُؤْمِنِينَ مَا يُكْرَهُ أَنْ يُنْتَبَذَ فِيهِ قَالَتْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْلَ الْبَيْتِ عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[23697,23697,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا اغْتَسَلَ مِنْ الْجَنَابَةِ تَمَضْمَضَ وَاسْتَنْشَقَ ‏","","",""],[23698,23698,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ حَسَّانَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُمَارَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا ‏ ‏عَائِشَةُ ‏ ‏فِي بَيْتِهَا إِذْ سَمِعَتْ صَوْتًا فِي ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَتْ مَا هَذَا قَالُوا ‏ ‏عِيرٌ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَدِمَتْ مِنْ ‏ ‏الشَّامِ ‏ ‏تَحْمِلُ مِنْ كُلِّ شَيْءٍ قَالَ فَكَانَتْ سَبْعَ مِائَةِ بَعِيرٍ قَالَ فَارْتَجَّتْ ‏ ‏الْمَدِينَةُ ‏ ‏مِنْ الصَّوْتِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَدْ ‏ ‏رَأَيْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏يَدْخُلُ الْجَنَّةَ ‏ ‏حَبْوًا ‏ ‏فَبَلَغَ ذَلِكَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏فَقَالَ إِنْ اسْتَطَعْتُ لَأَدْخُلَنَّهَا قَائِمًا فَجَعَلَهَا بِأَقْتَابِهَا وَأَحْمَالِهَا فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[23699,23699,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي رُكُوعِهِ ‏ ‏سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏فِي رُكُوعِهِ وَسُجُودِهِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَذَكَرْتُ ذَلِكَ ‏ ‏لِهِشَامِ بْنِ أَبِي عَبْدِ اللَّهِ ‏ ‏فَقَالَ ‏ ‏فِي رُكُوعِهِ وَسُجُودِهِ ‏","","",""],[23700,23700,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ قُسَيْطٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى قَامَ حَتَّى ‏ ‏تَتَفَطَّرَ ‏ ‏رِجْلَاهُ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَصْنَعُ هَذَا وَقَدْ غُفِرَ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏أَفَلَا أَكُونُ عَبْدًا شَكُورًا ‏","","",""],[23701,23701,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏عَنْ ‏ ‏أَبِي قُسَيْطٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ مِنْ عِنْدِهَا لَيْلًا قَالَتْ فَغِرْتُ عَلَيْهِ قَالَتْ فَجَاءَ فَرَأَى مَا أَصْنَعُ فَقَالَ مَا لَكِ يَا ‏ ‏عَائِشَةُ ‏ ‏أَغِرْتِ قَالَتْ فَقُلْتُ وَمَا لِي أَنْ لَا يَغَارَ مِثْلِي عَلَى مِثْلِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَأَخَذَكِ شَيْطَانُكِ قَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَمَعِي شَيْطَانٌ قَالَ نَعَمْ قُلْتُ وَمَعَ كُلِّ إِنْسَانٍ قَالَ نَعَمْ قُلْتُ وَمَعَكَ يَا رَسُولَ اللَّهِ قَالَ نَعَمْ وَلَكِنَّ رَبِّي عَزَّ وَجَلَّ أَعَانَنِي عَلَيْهِ حَتَّى أَسْلَمَ ‏","","",""],[23702,23702,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا خُيِّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَمْرَيْنِ إِلَّا اخْتَارَ أَيْسَرَهُمَا مَا لَمْ يَكُنْ إِثْمًا فَإِنْ كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ وَمَا انْتَقَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِنَفْسِهِ فِي أَمْرٍ يُنْتَهَكُ مِنْهُ إِلَّا أَنْ ‏ ‏تُنْتَهَكَ ‏ ‏لِلَّهِ عَزَّ وَجَلَّ حُرْمَةٌ فَيَنْتَقِمُ لِلَّهِ عَزَّ وَجَلَّ ‏","","",""],[23703,23703,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْغَلَّةُ ‏ ‏بِالضَّمَانِ ‏","","",""],[23704,23704,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْتَسِطُوهَا ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏فَجَعَلْنَاهُنَّ وِسَادَتَيْنِ ‏ ‏يَعْنِي السِّتْرَ ‏","","",""],[23705,23705,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏خَوَّاتِ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏أُمِّ عَمْرٍو بِنْتِ خَوَّاتٍ ‏ ‏أَنَّ امْرَأَةً قَالَتْ ‏ ‏لِعَائِشَةَ ‏ ‏إِنَّ ابْنَتِي أَصَابَهَا مَرَضٌ فَسَقَطَ شَعَرُهَا فَهُوَ مُوَفَّرٌ لَا أَسْتَطِيعُ أَنْ أُمَشِّطَهُ وَهِيَ عَرُوسٌ أَفَأَصِلُ فِي شَعَرِهَا قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَاصِلَةَ ‏ ‏وَالْمُسْتَوْصِلَةَ ‏","","",""],[23706,23706,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ نَاسٌ مِنْ ‏ ‏الْيَهُودِ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا السَّامُ عَلَيْكَ فَقَالَ عَلَيْكُمْ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏عَلَيْكُمْ لَعْنَةُ اللَّهِ وَلَعْنَةُ اللَّاعِنِينَ قَالُوا مَا كَانَ ‏ ‏أَبُوكِ ‏ ‏فَحَّاشًا فَلَمَّا خَرَجُوا قَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا حَمَلَكِ عَلَى مَا صَنَعْتِ قَالَتْ أَمَا سَمِعْتَ مَا قَالُوا قَالَ فَمَا ‏ ‏رَأَيْتِينِي قُلْتُ عَلَيْكُمْ إِنَّهُ يُصِيبُهُمْ مَا أَقُولُ لَهُمْ وَلَا يُصِيبُنِي مَا قَالُوا لِي ‏","","",""],[23707,23707,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ امْرَأَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏جَاءَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ ابْنَتِي ‏ ‏اشْتَكَتْ ‏ ‏فَسَقَطَ شَعَرُ رَأْسِهَا وَإِنَّ زَوْجَهَا قَدْ أَشْقَانِي ‏ ‏أَفَتَرَى أَنْ أَصِلَ بِرَأْسِهَا فَقَالَ لَا فَإِنَّهُ ‏ ‏لُعِنَ ‏ ‏الْمَوْصُولَاتُ ‏","","",""],[23708,23708,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُفَضَّلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ الْأَيْلِىُّ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَتَى إِلَى فِرَاشِهِ فِي كُلِّ لَيْلَةٍ جَمَعَ كَفَّيْهِ ثُمَّ ‏ ‏نَفَثَ ‏ ‏فِيهِمَا وَقَرَأَ فِيهِمَا ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏وَقُلْ أَعُوذُ بِرَبِّ ‏ ‏الْفَلَقِ ‏ ‏وَقُلْ أَعُوذُ بِرَبِّ النَّاسِ ‏ ‏ثُمَّ مَسْحَ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ مَا أَقْبَلَ مِنْ جَسَدِهِ يَفْعَلُ ذَلِكَ ثَلَاثَ مَرَّاتٍ ‏","","",""],[23709,23709,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏وَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَقْنِي عَلَى مَنْكِبَيْهِ لِأَنْظُرَ إِلَى ‏ ‏زَفْنِ ‏ ‏الْحَبَشَةِ ‏ ‏حَتَّى كُنْتُ الَّتِي مَلِلْتُ فَانْصَرَفْتُ عَنْهُمْ ‏","","",""],[23710,23710,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏عُرْوَةُ ‏ ‏إِنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ لَتَعْلَمُ ‏ ‏يَهُودُ ‏ ‏أَنَّ فِي دِينِنَا فُسْحَةً إِنِّي أُرْسِلْتُ بِحَنِيفِيَّةٍ سَمْحَةٍ ‏","","",""],[23711,23711,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ الطَّالْقَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَنْبَسَةَ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَتَدْرِي مَا سِعَةُ جَهَنَّمَ قُلْتُ لَا قَالَ أَجَلْ وَاللَّهِ مَا تَدْرِي أَنَّ بَيْنَ شَحْمَةِ أُذُنِ أَحَدِهِمْ وَبَيْنَ ‏ ‏عَاتِقِهِ ‏ ‏مَسِيرَةَ سَبْعِينَ خَرِيفًا ‏ ‏تَجْرِي فِيهَا أَوْدِيَةُ الْقَيْحِ وَالدَّمِ قُلْتُ أَنْهَارًا قَالَ لَا بَلْ أَوْدِيَةً ثُمَّ قَالَ أَتَدْرُونَ مَا سِعَةُ جَهَنَّمَ قُلْتُ لَا قَالَ أَجَلْ وَاللَّهِ مَا تَدْرِي حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّهَا سَأَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قَوْلِهِ ‏ { ‏وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ ‏} ‏فَأَيْنَ النَّاسُ يَوْمَئِذٍ يَا رَسُولَ اللَّهِ قَالَ هُمْ ‏ ‏عَلَى جِسْرِ جَهَنَّمَ ‏","","",""],[23712,23712,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَائِشَةُ ‏ ‏هَذَا ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَهُوَ يَقْرَأُ عَلَيْكِ السَّلَامَ فَقُلْتُ عَلَيْكَ وَعَلَيْهِ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ ‏ ‏تَرَى مَا لَا نَرَى يَا رَسُولَ اللَّهِ ‏","","",""],[23713,23713,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏وَيُونُسَ ‏ ‏وَعَلِيِّ بْنِ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَيُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏لَمَّا ‏ ‏ثَقُلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاشْتَدَّ وَجَعُهُ اسْتَأْذَنَ أَزْوَاجَهُ فِي أَنْ يُمَرَّضَ فِي بَيْتِي فَأَذِنَّ لَهُ ‏","","",""],[23714,23714,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏وَعَلِيٌّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ سَفَرًا أَقْرَعَ بَيْنَ نِسَائِهِ فَأَيَّتُهُنَّ خَرَجَ سَهْمُهَا خَرَجَ بِهَا مَعَهُ وَكَانَ يَقْسِمُ لِكُلِّ امْرَأَةٍ مِنْهُنَّ يَوْمَهَا وَلَيْلَتَهَا غَيْرَ أَنَّ ‏ ‏سَوْدَةَ بِنْتَ زَمْعَةَ ‏ ‏كَانَتْ وَهَبَتْ يَوْمَهَا وَلَيْلَتَهَا ‏ ‏لِعَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَبْتَغِي بِذَلِكَ رِضَا النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23715,23715,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏وَمَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ الْمُؤَذِّنُ إِذَا سَكَتَ مِنْ صَلَاةِ الصُّبْحِ ‏ ‏صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ تَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23716,23716,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مِهْزَمٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏كَرِيمَةُ ابْنَةُ هَمَّامٍ ‏ ‏قَالَتْ ‏ ‏دَخَلْتُ ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏ ‏فَأَخْلَوْهُ ‏ ‏لِعَائِشَةَ ‏ ‏فَسَأَلَتْهَا امْرَأَةٌ ‏ ‏مَا تَقُولِي يَا أُمَّ الْمُؤْمِنِينَ فِي الْحِنَّاءِ فَقَالَتْ كَانَ حَبِيبِي ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ لَوْنُهُ وَيَكْرَهُ رِيحَهُ وَلَيْسَ بِمُحَرَّمٍ عَلَيْكُنَّ بَيْنَ كُلِّ حَيْضَتَيْنِ أَوْ عِنْدَ كُلِّ حَيْضَةٍ ‏","","",""],[23717,23717,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورِ ابْنِ صَفِيَّةَ ‏ ‏أَنَّ ‏ ‏أُمَّهُ ‏ ‏صَفِيَّةَ بِنْتَ شَيْبَةَ ‏ ‏حَدَّثَتْهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَّكِئُ فِي حِجْرِي وَأَنَا حَائِضٌ ثُمَّ يَقْرَأُ الْقُرْآنَ ‏","","",""],[23718,23718,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏وَمَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ الصِّدِّيقَ ‏ ‏دَخَلَ عَلَيْهَا ‏ ‏فَتَيَمَّمَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُسَجًّى ‏ ‏بِبُرْدِ ‏ ‏حِبَرَةٍ ‏ ‏فَكَشَفَ عَنْ وَجْهِهِ ثُمَّ ‏ ‏أَكَبَّ ‏ ‏عَلَيْهِ فَقَبَّلَهُ وَبَكَى ثُمَّ قَالَ بِأَبِي وَأُمِّي وَاللَّهِ ‏ ‏لَا يَجْمَعُ اللَّهُ عَزَّ وَجَلَّ عَلَيْكَ مَوْتَتَيْنِ أَبَدًا أَمَّا الْمَوْتَةُ الَّتِي قَدْ كُتِبَتْ عَلَيْكَ فَقَدْ مِتَّهَا ‏","","",""],[23719,23719,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُجَالِدٌ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ذَكَرَ ‏ ‏خَدِيجَةَ ‏ ‏أَثْنَى عَلَيْهَا فَأَحْسَنَ الثَّنَاءَ قَالَتْ فَغِرْتُ يَوْمًا فَقُلْتُ مَا أَكْثَرَ مَا تَذْكُرُهَا حَمْرَاءَ ‏ ‏الشِّدْقِ ‏ ‏قَدْ أَبْدَلَكَ اللَّهُ عَزَّ وَجَلَّ بِهَا خَيْرًا مِنْهَا قَالَ ‏ ‏مَا أَبْدَلَنِي اللَّهُ عَزَّ وَجَلَّ خَيْرًا مِنْهَا قَدْ آمَنَتْ بِي إِذْ كَفَرَ بِي النَّاسُ وَصَدَّقَتْنِي إِذْ كَذَّبَنِي النَّاسُ وَوَاسَتْنِي بِمَالِهَا إِذْ حَرَمَنِي النَّاسُ وَرَزَقَنِي اللَّهُ عَزَّ وَجَلَّ وَلَدَهَا إِذْ حَرَمَنِي أَوْلَادَ النِّسَاءِ ‏","","",""],[23720,23720,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أَلَا يُعْجِبُكَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏جَاءَ فَجَلَسَ إِلَى جَانِبِ حُجْرَتِي يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسْمِعُنِي ذَلِكَ وَكُنْتُ ‏ ‏أُسَبِّحُ ‏ ‏فَقَامَ قَبْلَ أَنْ أَقْضِيَ سُبْحَتِي وَلَوْ أَدْرَكْتُهُ لَرَدَدْتُ عَلَيْهِ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَكُنْ ‏ ‏يَسْرُدُ ‏ ‏الْحَدِيثَ ‏ ‏كَسَرْدِكُمْ ‏","","",""],[23721,23721,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏ ‏يُبَادِرُنِي ‏ ‏وَأُبَادِرُهُ ‏ ‏وَأَقُولُ دَعْ لِي دَعْ لِي ‏","","",""],[23722,23722,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏تَزَوَّجَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ابْنَةُ سِتِّ سِنِينَ ‏ ‏بِمَكَّةَ ‏ ‏مُتَوَفَّى ‏ ‏خَدِيجَةَ ‏ ‏وَدَخَلَ بِي وَأَنَا ابْنَةُ تِسْعِ سِنِينَ ‏ ‏بِالْمَدِينَةِ ‏","","",""],[23723,23723,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنْ كَانَ ‏ ‏لَيُوحَى إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏فَتَضْرِبُ ‏ ‏بِجِرَانِهَا ‏","","",""],[23724,23724,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏قَالَ لَهَا يَا بُنَيَّةُ ‏ ‏أَيُّ يَوْمٍ تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ يَوْمَ ‏ ‏الِاثْنَيْنِ قَالَ فِي كَمْ كَفَّنْتُمْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ يَا ‏ ‏أَبَتِ كَفَّنَّاهُ فِي ثَلَاثَةِ أَثْوَابٍ بِيضٍ سُحُولِيَّةٍ جُدُدٍ يَمَانِيَةٍ لَيْسَ فِيهَا قَمِيصٌ وَلَا عِمَامَةٌ ‏ ‏أُدْرِجَ ‏ ‏فِيهَا إِدْرَاجًا ‏","","",""],[23725,23725,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَهُ ‏ ‏يَا ابْنَ أُخْتِي لَقَدْ رَأَيْتُ مِنْ تَعْظِيمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَمَّهُ أَمْرًا عَجِيبًا وَذَلِكَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَتْ تَأْخُذُهُ الْخَاصِرَةُ فَيَشْتَدُّ بِهِ جِدًّا فَكُنَّا نَقُولُ أَخَذَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِرْقُ ‏ ‏الْكُلْيَةِ ‏ ‏لَا ‏ ‏نَهْتَدِي أَنْ نَقُولَ الْخَاصِرَةَ ثُمَّ أَخَذَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا فَاشْتَدَّتْ بِهِ جِدًّا حَتَّى أُغْمِيَ عَلَيْهِ وَخِفْنَا عَلَيْهِ وَفَزِعَ النَّاسُ إِلَيْهِ فَظَنَنَّا أَنَّ بِهِ ‏ ‏ذَاتَ الْجَنْبِ ‏ ‏فَلَدَدْنَاهُ ثُمَّ ‏ ‏سُرِّيَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَفَاقَ فَعَرَفَ أَنَّهُ قَدْ ‏ ‏لُدَّ ‏ ‏وَوَجَدَ أَثَرَ ‏ ‏اللَّدُودِ ‏ ‏فَقَالَ ظَنَنْتُمْ أَنَّ اللَّهَ عَزَّ وَجَلَّ سَلَّطَهَا عَلَيَّ مَا كَانَ اللَّهُ يُسَلِّطُهَا عَلَيَّ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَا يَبْقَى فِي الْبَيْتِ أَحَدٌ إِلَّا ‏ ‏لُدَّ ‏ ‏إِلَّا عَمِّي فَرَأَيْتُهُمْ ‏ ‏يَلُدُّونَهُمْ ‏ ‏رَجُلًا رَجُلًا قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏وَمَنْ فِي الْبَيْتِ يَوْمَئِذٍ فَتَذْكُرُ فَضْلَهُمْ ‏ ‏فَلُدَّ ‏ ‏الرِّجَالُ أَجْمَعُونَ وَبَلَغَ ‏ ‏اللَّدُودُ ‏ ‏أَزْوَاجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلُدِدْنَ ‏ ‏امْرَأَةٌ امْرَأَةٌ حَتَّى بَلَغَ ‏ ‏اللَّدُودُ ‏ ‏امْرَأَةً مِنَّا ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏لَا أَعْلَمُهَا إِلَّا ‏ ‏مَيْمُونَةَ ‏ ‏قَالَ وَقَالَ بَعْضُ النَّاسِ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏قَالَتْ إِنِّي وَاللَّهِ صَائِمَةٌ فَقُلْنَا بِئْسَمَا ظَنَنْتِ أَنْ نَتْرُكَكِ وَقَدْ أَقْسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَدَدْنَاهَا ‏ ‏وَاللَّهِ يَا ابْنَ أُخْتِي وَإِنَّهَا لَصَائِمَةٌ ‏","","",""],[23726,23726,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ ‏ ‏شَعْرُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دُونَ ‏ ‏الْجَمَّةِ ‏ ‏وَفَوْقَ ‏ ‏الْوَفْرَةِ ‏","","",""],[23727,23727,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَنَامَ وَهُوَ جُنُبٌ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ وَإِذَا أَرَادَ أَنْ يَأْكُلَ وَيَشْرَبَ قَالَتْ يَغْسِلُ يَدَيْهِ ثُمَّ يَأْكُلُ وَيَشْرَبُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏صَالِحُ بْنُ أَبِي الْأَخْضَرِ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏وَعُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏يُونُسَ ‏","","",""],[23728,23728,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَنَامَ وَهُوَ جُنُبٌ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ فَإِذَا أَرَادَ أَنْ يَأْكُلَ غَسَلَ يَدَيْهِ ثُمَّ أَكَلَ ‏","","",""],[23729,23729,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ نُعَيْمٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ مِخْرَاقٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏يَا أُمَّ الْمُؤْمِنِينَ إِنَّ نَاسًا يَقْرَأُ أَحَدُهُمْ الْقُرْآنَ فِي لَيْلَةٍ مَرَّتَيْنِ أَوْ ثَلَاثًا فَقَالَتْ أُولَئِكَ قَرَءُوا وَلَمْ يَقْرَءُوا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُومُ اللَّيْلَةَ التَّمَامَ فَيَقْرَأُ سُورَةَ ‏ ‏الْبَقَرَةِ ‏ ‏وَسُورَةَ ‏ ‏آلِ ‏ ‏عِمْرَانَ ‏ ‏وَسُورَةَ ‏ ‏النِّسَاءِ ‏ ‏ثُمَّ لَا يَمُرُّ بِآيَةٍ فِيهَا اسْتِبْشَارٌ إِلَّا دَعَا اللَّهَ عَزَّ وَجَلَّ ‏ ‏وَرَغِبَ ‏ ‏وَلَا يَمُرُّ بِآيَةٍ فِيهَا تَخْوِيفٌ إِلَّا دَعَا اللَّهَ عَزَّ وَجَلَّ وَاسْتَعَاذَ ‏","","",""],[23730,23730,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْمَرُ بْنُ بِشْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ فَمِنَّا مَنْ ‏ ‏أَهَلَّ ‏ ‏بِحَجٍّ وَمِنَّا مَنْ ‏ ‏أَهَلَّ ‏ ‏بِعُمْرَةٍ ‏ ‏فَأَهْدَى ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏أَهَلَّ ‏ ‏بِالْعُمْرَةِ وَلَمْ ‏ ‏يُهْدِ ‏ ‏فَلْيَحِلَّ ‏ ‏وَمَنْ ‏ ‏أَهَلَّ ‏ ‏فَأَهْدَى ‏ ‏فَلَا ‏ ‏يَحِلَّ ‏ ‏وَمَنْ ‏ ‏أَهَلَّ ‏ ‏بِحَجٍّ فَلْيُتِمَّ حَجَّهُ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏وَكُنْتُ مِمَّنْ ‏ ‏أَهَلَّ ‏ ‏بِعُمْرَةٍ ‏","","",""],[23731,23731,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا رَأَى الْمَطَرَ قَالَ ‏ ‏اللَّهُمَّ صَيِّبًا هَنِيئًا ‏","","",""],[23732,23732,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَغْتَسِلُ وَيُصَلِّي الرَّكْعَتَيْنِ لَا ‏ ‏أُرَاهُ يُحْدِثُ وُضُوءًا بَعْدَ الْغُسْلِ ‏","","",""],[23733,23733,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّ ‏ ‏سَلَمَةَ بِنْتَ سُهَيْلِ بْنِ عَمْرٍو ‏ ‏اسْتُحِيضَتْ ‏ ‏فَأَتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَتْهُ عَنْ ذَلِكَ ‏ ‏فَأَمَرَهَا بِالْغُسْلِ عِنْدَ كُلِّ صَلَاةٍ فَلَمَّا ‏ ‏جَهَدَهَا ‏ ‏ذَلِكَ أَمَرَهَا أَنْ تَجْمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ بِغُسْلٍ وَالْمَغْرِبِ وَالْعِشَاءِ بِغُسْلٍ وَالصُّبْحَ بِغُسْلٍ ‏","","",""],[23734,23734,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبَّادٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَدِمَتْ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِلْيَةٌ مِنْ عِنْدِ ‏ ‏النَّجَاشِيِّ ‏ ‏أَهْدَاهَا لَهُ فِيهَا خَاتَمٌ مِنْ ذَهَبٍ فِيهِ فَصٌّ حَبَشِيٌّ فَأَخَذَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعُودٍ بِبَعْضِ أَصَابِعِهِ مُعْرِضًا عَنْهُ ثُمَّ دَعَا ‏ ‏أُمَامَةَ بِنْتَ أَبِي الْعَاصِ ‏ ‏ابْنَةَ ابْنَتِهِ فَقَالَ ‏ ‏تَحَلَّيْ بِهَذَا يَا بُنَيَّةُ ‏","","",""],[23735,23735,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَّامُ بْنُ أَبِي مُطِيعٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ يَزِيدَ الْجُعْفِيِّ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْجَزَّارِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ غَسَّلَ مَيِّتًا فَأَدَّى فِيهِ الْأَمَانَةَ وَلَمْ يُفْشِ عَلَيْهِ مَا يَكُونُ مِنْهُ عِنْدَ ذَلِكَ خَرَجَ مِنْ ‏ ‏ذُنُوبِهِ كَيَوْمِ وَلَدَتْهُ أُمُّهُ قَالَ لِيَلِهِ أَقْرَبُكُمْ مِنْهُ إِنْ كَانَ يَعْلَمُ فَإِنْ كَانَ لَا يَعْلَمُ فَمَنْ تَرَوْنَ أَنَّ عِنْدَهُ حَظًّا مِنْ وَرَعٍ وَأَمَانَةٍ ‏","","",""],[23736,23736,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏أَبَا عَمْرٍو ‏ ‏مَوْلَى ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا أَخْبَرَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَكُونُ جُنُبًا فَيُرِيدُ الرُّقَادَ ‏ ‏فَيَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ يَرْقُدُ ‏","","",""],[23737,23737,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ عَمَرَ أَرْضًا لَيْسَتْ لِأَحَدٍ فَهُوَ أَحَقُّ بِهَا ‏","","",""],[23738,23738,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُصِيبَةٍ يُصَابُ بِهَا مُسْلِمٌ إِلَّا كُفِّرَ عَنْهُ حَتَّى الشَّوْكَةِ يُشَاكُهَا ‏","","",""],[23739,23739,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مُنْهَبِطًا قَدْ مَلَأَ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ وَعَلَيْهِ ثِيَابُ سُنْدُسٍ مُعَلَّقًا بِهِ اللُّؤْلُؤُ وَالْيَاقُوتُ ‏","","",""],[23740,23740,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّ ‏ ‏مُعَاذَةَ ‏ ‏حَدَّثَتْهُ قَالَتْ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَتُجْزِئُ إِحْدَانَا صَلَاتَهَا إِذَا طَهُرَتْ فَقَالَتْ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ ‏ ‏كُنَّا نَحِيضُ وَنَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا نَفْعَلُ ذَلِكَ ‏ ‏أَوْ قَالَتْ لَمْ يَأْمُرْنَا بِذَلِكَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَاه ‏ ‏بَهْزٌ ‏ ‏وَلَمْ يَقُلْ حَدَّثَتْنِي ‏ ‏مُعَاذَةُ ‏ ‏وَقَالَ عَنْ وَعَنْ ‏","","",""],[23741,23741,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبِيدَةُ بْنُ أَبِي رَائِطَةَ الْمُجَاشِعِيُّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُعَاوِيَةُ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَتْنِي ‏ ‏عَمَّتِي ‏ ‏عَائِشَةُ بِنْتُ طَلْحَةَ ‏ ‏عَنْ ‏ ‏خَالَتِهَا ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جِهَادُ النِّسَاءِ حَجُّ هَذَا ‏ ‏الْبَيْتِ ‏","","",""],[23742,23742,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏قَالَتْ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏كَمْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى قَالَتْ أَرْبَعَ رَكَعَاتٍ وَيَزِيدُ مَا شَاءَ اللَّهُ ‏","","",""],[23743,23743,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مُرْنَ أَزْوَاجَكُنَّ أَنْ يَغْسِلُوا عَنْهُمْ أَثَرَ الْخَلَاءِ وَالْبَوْلِ فَإِنَّا ‏ ‏نَسْتَحْيِي أَنْ ‏ ‏نَنْهَاهُمْ عَنْ ذَلِكَ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏","","",""],[23744,23744,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا مَرِضَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذْتُ يَدَهُ فَجَعَلْتُ أُمِرُّهَا عَلَى صَدْرِهِ وَدَعَوْتُ بِهَذِهِ الْكَلِمَاتِ أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ فَانْتَزَعَ يَدَهُ مِنْ يَدِي وَقَالَ ‏ ‏أَسْأَلُ اللَّهَ الرَّفِيقَ الْأَعْلَى الْأَسْعَدَ ‏","","",""],[23745,23745,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ جُدْعَانَ ‏ ‏كَانَ فِي الْجَاهِلِيَّةِ ‏ ‏يَقْرِي الضَّيْفَ وَيَفُكُّ ‏ ‏الْعَانِيَ ‏ ‏وَيَصِلُ الرَّحِمَ وَيُحْسِنُ الْجِوَارَ فَأَثْنَيْتُ عَلَيْهِ فَهَلْ يَنْفَعُهُ ذَلِكَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا إِنَّهُ لَمْ يَقُلْ يَوْمًا قَطُّ اللَّهُمَّ اغْفِرْ لِي يَوْمَ الدِّينِ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً فَأَثْنَيْتُ عَلَيْهِ ‏","","",""],[23746,23746,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْنَى عَلَيَّ فَقَالَ ‏ ‏إِنَّكُنَّ لَأَهَمُّ ‏ ‏مَا أَتْرُكُ إِلَى وَرَاءِ ظَهْرِي وَاللَّهِ لَا يَعْطِفُ عَلَيْكُنَّ إِلَّا الصَّابِرُونَ ‏ ‏أَوْ الصَّادِقُونَ ‏","","",""],[23747,23747,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَى الرِّيحَ قَدْ اشْتَدَّتْ تَغَيَّرَ وَجْهُهُ ‏","","",""],[23748,23748,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِلَالُ بْنُ أَبِي حُمَيْدٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ الَّذِي لَمْ يَقُمْ مِنْهُ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ قَالَ قُلْتُ وَلَوْلَا ذَلِكَ أُبْرِزَ قَبْرُهُ غَيْرَ أَنَّهُ خَشِيَ أَنْ يُتَّخَذَ مَسْجِدًا ‏","","",""],[23749,23749,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏عَنْ ‏ ‏أَبِي عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ ‏","","",""],[23750,23750,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏بِالْمُدِّ ‏ ‏وَيَغْتَسِلُ بِنَحْوِ ‏ ‏الصَّاعِ ‏","","",""],[23751,23751,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏صَفِيَّةُ بِنْتُ شَيْبَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَوَضَّأُ ‏ ‏بِالْمُدِّ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً بِقَدْرِ مُدٍّ وَيَغْتَسِلُ ‏ ‏بِالصَّاعِ ‏","","",""],[23752,23752,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏فِرَاسٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏اجْتَمَعَ أَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَهُ ذَاتَ يَوْمٍ فَقُلْنَ يَا نَبِيَّ اللَّهِ ‏ ‏أَيَّتُنَا أَسْرَعُ بِكَ لُحُوقًا فَقَالَ أَطْوَلُكُنَّ يَدًا فَأَخَذْنَا قَصَبًا فَذَرَعْنَاهَا فَكَانَتْ ‏ ‏سَوْدَةُ بِنْتُ زَمْعَةَ ‏ ‏أَطْوَلَنَا ذِرَاعًا فَقَالَتْ تُوُفِّيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَتْ ‏ ‏سَوْدَةُ ‏ ‏أَسْرَعَنَا بِهِ لُحُوقًا فَعَرَفْنَا بَعْدُ إِنَّمَا كَانَ طُولُ يَدِهَا مِنْ الصَّدَقَةِ وَكَانَتْ امْرَأَةً تُحِبُّ الصَّدَقَةَ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً ‏ ‏قَصَبَةً ‏ ‏نَذْرَعُهَا ‏","","",""],[23753,23753,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏أُمُّ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏لَا يَرْقُدُ لَيْلًا وَلَا نَهَارًا فَيَسْتَيْقِظُ إِلَّا تَسَوَّكَ ‏","","",""],[23754,23754,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنِّي عَلَى الْحَوْضِ أَنْتَظِرُ مَنْ يَرِدُهُ عَلَيَّ مِنْكُمْ فَلَيُقَطَّعَنَّ رِجَالٌ دُونِي فَلَأَقُولَنَّ يَا رَبِّ أُمَّتِي أُمَّتِي فَلَيُقَالَنَّ لِي إِنَّكَ لَا تَدْرِي مَا عَمِلُوا بَعْدَكَ مَا زَالُوا يَرْجِعُونَ عَلَى ‏ ‏أَعْقَابِهِمْ ‏","","",""],[23755,23755,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَرَادَ أَنْ يَرْقُدَ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ يَرْقُدُ ‏","","",""],[23756,23756,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَهْدِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏سُئِلَتْ مَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْمَلُ فِي بَيْتِهِ قَالَتْ كَانَ ‏ ‏يَخِيطُ ثَوْبَهُ ‏ ‏وَيَخْصِفُ ‏ ‏نَعْلَهُ وَيَعْمَلُ مَا يَعْمَلُ الرِّجَالُ فِي بُيُوتِهِمْ ‏","","",""],[23757,23757,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏أَبُو الْمُؤَمَّلِ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا صَلَّى رَكْعَتَيْنِ قَبْلَ الْفَجْرِ رُبَّمَا اضْطَجَعَ ‏","","",""],[23758,23758,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَأْسُهُ بَيْنَ ‏ ‏سَحْرِي ‏ ‏وَنَحْرِي ‏ ‏قَالَتْ فَلَمَّا خَرَجَتْ نَفْسُهُ لَمْ أَجِدْ ‏ ‏رِيحًا قَطُّ أَطْيَبَ مِنْهَا ‏","","",""],[23759,23759,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ الْمُعْتَمِرِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا نُرَى إِلَّا إِنَّمَا هُوَ الْحَجُّ فَقَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏فَطَافَ وَلَمْ ‏ ‏يَحْلِلْ ‏ ‏وَكَانَ مَعَهُ ‏ ‏الْهَدْيُ ‏ ‏فَطَافَ مَنْ مَعَهُ مِنْ نِسَائِهِ وَأَصْحَابِهِ ‏ ‏فَحَلَّ ‏ ‏مِنْهُمْ مَنْ لَمْ يَكُنْ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏وَحَاضَتْ هِيَ فَقَضَيْنَا مَنَاسِكَنَا مِنْ حَجِّنَا فَلَمَّا كَانَتْ لَيْلَةُ ‏ ‏الْحَصْبَةِ ‏ ‏لَيْلَةُ ‏ ‏النَّفْرِ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏أَيَرْجِعُ أَصْحَابُكَ بِحَجٍّ وَعُمْرَةٍ وَأَرْجِعُ أَنَا بِحَجٍّ فَقَالَ أَمَا كُنْتِ طُفْتِ ‏ ‏لَيَالِيَ قَدِمْنَا قَالَتْ قُلْتُ لَا قَالَ انْطَلِقِي مَعَ ‏ ‏أَخِيكِ ‏ ‏إِلَى ‏ ‏التَّنْعِيمِ ‏ ‏فَأَهِلِّي ‏ ‏بِعُمْرَةٍ ثُمَّ مَوْعِدُكِ مَكَانَ كَذَا وَكَذَا قَالَتْ وَحَاضَتْ ‏ ‏صَفِيَّةُ ‏ ‏فَقَالَ عَقْرَى أَوْ حَلْقَى إِنَّكِ لَحَابِسَتُنَا أَمَا كُنْتِ طُفْتِ ‏ ‏بِالْبَيْتِ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏قَالَتْ بَلَى قَالَ لَا بَأْسَ ‏ ‏فَانْفِرِي ‏ ‏قَالَتْ فَلَقِيتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُدْلِجًا وَهُوَ ‏ ‏مُصْعِدٌ ‏ ‏عَلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏وَأَنَا ‏ ‏مُنْهَبِطَةٌ ‏ ‏عَلَيْهِمْ ‏ ‏أَوْ هُوَ ‏ ‏مُنْهَبِطٌ ‏ ‏عَلَيْهِمْ وَأَنَا ‏ ‏مُصْعِدَةٌ ‏","","",""],[23760,23760,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏امْرَأَةً ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏كَيْفَ أَغْتَسِلُ عِنْدَ الطُّهْرِ فَقَالَ خُذِي ‏ ‏فِرْصَةً ‏ ‏مُمَسَّكَةً ‏ ‏فَتَوَضَّئِي قَالَتْ كَيْفَ أَتَوَضَّأُ بِهَا قَالَ تَوَضَّئِي بِهَا قَالَتْ كَيْفَ أَتَوَضَّأُ بِهَا ثُمَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبَّحَ فَأَعْرَضَ عَنْهَا ثُمَّ قَالَ تَوَضَّئِي بِهَا قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَفَطِنْتُ لِمَا يُرِيدُ رَسُولُ اللَّهِ فَأَخَذْتُهَا فَجَذَبْتُهَا إِلَيَّ فَأَخْبَرْتُهَا بِمَا يُرِيدُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23761,23761,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَرْوَانُ أَبُو لُبَابَةَ ‏ ‏مِنْ ‏ ‏بَنِي عُقَيْلٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ حَتَّى نَقُولَ مَا يُرِيدُ أَنْ يُفْطِرَ وَيُفْطِرُ حَتَّى نَقُولَ مَا يُرِيدُ أَنْ يَصُومَ وَكَانَ يَقْرَأُ كُلَّ لَيْلَةٍ ‏ ‏بِبَنِي إِسْرَائِيلَ ‏ ‏وَالزُّمَرِ ‏","","",""],[23762,23762,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏وَحَدَّثَنِيهِ ‏ ‏مَكْحُولٌ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا اسْتُحِلَّ بِهِ فَرْجُ الْمَرْأَةِ مِنْ مَهْرٍ أَوْ عِدَّةٍ فَهُوَ لَهَا وَمَا أُكْرِمَ بِهِ أَبُوهَا أَوْ أَخُوهَا أَوْ وَلِيُّهَا بَعْدَ عُقْدَةِ النِّكَاحِ فَهُوَ لَهُ وَأَحَقُّ مَا أُكْرِمَ بِهِ الرَّجُلُ ابْنَتُهُ وَأُخْتُهُ ‏","","",""],[23763,23763,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَلَّامُ بْنُ أَبِي مُطِيعٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْجَزَّارِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏مَنْ غَسَّلَ مَيِّتًا فَأَدَّى فِيهِ الْأَمَانَةَ ‏ ‏يَعْنِي أَنْ لَا يُفْشِيَ عَلَيْهِ مَا يَكُونُ مِنْهُ عِنْدَ ذَلِكَ ‏ ‏كَانَ مِنْ ذُنُوبِهِ كَيَوْمِ وَلَدَتْهُ أُمُّهُ قَالَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلْيَلِهِ أَقْرَبُ أَهْلِهِ مِنْهُ إِنْ كَانَ يَعْلَمُ فَإِنْ كَانَ لَا يَعْلَمُ فَلْيَلِهِ مِنْكُمْ مَنْ تَرَوْنَ أَنَّ عِنْدَهُ حَظًّا مِنْ وَرَعٍ أَوْ أَمَانَةٍ ‏","","",""],[23764,23764,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَمْسٌ ‏ ‏فَوَاسِقُ ‏ ‏يُقْتَلْنَ فِي الْحِلِّ وَالْحَرَمِ الْكَلْبُ ‏ ‏الْعَقُورُ ‏ ‏وَالْفَأْرَةُ وَالْحُدَيَّا وَالْغُرَابُ وَالْعَقْرَبُ ‏","","",""],[23765,23765,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ نَاسًا كَانُوا يَتَعَبَّدُونَ عِبَادَةً شَدِيدَةً فَنَهَاهُمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ وَاللَّهِ ‏ ‏إِنِّي لَأَعْلَمُكُمْ بِاللَّهِ عَزَّ وَجَلَّ ‏ ‏وَأَخْشَاكُمْ لَهُ وَكَانَ يَقُولُ عَلَيْكُمْ مِنْ الْعَمَلِ مَا تُطِيقُونَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَمَلُّ حَتَّى تَمَلُّوا ‏","","",""],[23766,23766,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْتَهِدُ فِي الْعَشْرِ مَا لَا يَجْتَهِدُ فِي غَيْرِهِ ‏","","",""],[23767,23767,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ النُّعْمَانِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا الْتَقَى الْخِتَانَانِ اغْتَسَلَ ‏","","",""],[23768,23768,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏وَعَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏ ‏يُبَادِرُنِي ‏ ‏مُبَادَرَةً ‏","","",""],[23769,23769,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ أَوْسٍ ‏ ‏عَنْ ‏ ‏مِصْدَعٍ أَبِي يَحْيَى الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُهَا وَهُوَ صَائِمٌ وَيَمُصُّ لِسَانَهَا ‏ ‏قُلْتُ ‏ ‏سَمِعْتَهُ مِنْ ‏ ‏سَعْدِ بْنِ أَوْسٍ ‏ ‏قَالَ نَعَمْ ‏","","",""],[23770,23770,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُهْدِيَ إِلَيْهِ ضَبٌّ فَلَمْ يَأْكُلْهُ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَلَا أُطْعِمُهُ الْمَسَاكِينَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُطْعِمُوهُمْ مِمَّا لَا تَأْكُلُونَ ‏","","",""],[23771,23771,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَبِيبٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَزِّمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي ‏ ‏ذُيُولِ ‏ ‏النِّسَاءِ شِبْرًا قَالَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏إِذَنْ تَخْرُجَ سُوقُهُنَّ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً أَسْوُقُهُنَّ ‏ ‏قَالَ فَذِرَاعٌ ‏","","",""],[23772,23772,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي عُتْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهُ كَانَ تُصُدِّقَ عَلَى ‏ ‏بَرِيرَةَ ‏ ‏مِنْ لَحْمِ الصَّدَقَةِ فَأَهْدَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ لَهُ إِنَّهُ مِنْ لَحْمِ الصَّدَقَةِ فَقَالَ ‏ ‏إِنَّهُ لَهَا صَدَقَةٌ وَلَنَا هَدِيَّةٌ ‏","","",""],[23773,23773,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَهِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ أَصْوَاتًا فَقَالَ مَا هَذِهِ الْأَصْوَاتُ قَالُوا النَّخْلُ يُؤَبِّرُونَهُ يَا رَسُولَ اللَّهِ فَقَالَ لَوْ لَمْ يَفْعَلُوا لَصَلُحَ فَلَمْ يُؤَبِّرُوا ‏ ‏عَامَئِذٍ فَصَارَ ‏ ‏شِيصًا ‏ ‏فَذَكَرُوا ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِذَا كَانَ شَيْئًا مِنْ أَمْرِ دُنْيَاكُمْ فَشَأْنَكُمْ بِهِ وَإِذَا كَانَ شَيْئًا مِنْ أَمْرِ دِينِكُمْ فَإِلَيَّ ‏","","",""],[23774,23774,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَرْقُدُ فَإِذَا اسْتَيْقَظَ تَسَوَّكَ ثُمَّ تَوَضَّأَ ثُمَّ صَلَّى ثَمَانِ رَكَعَاتٍ يَجْلِسُ فِي كُلِّ رَكْعَتَيْنِ فَيُسَلِّمُ ثُمَّ يُوتِرُ بِخَمْسِ رَكَعَاتٍ لَا يَجْلِسُ إِلَّا فِي الْخَامِسَةِ وَلَا يُسَلِّمُ إِلَّا فِي الْخَامِسَةِ ‏","","",""],[23775,23775,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَعْقِلٍ الْمُحَارِبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نَنْبِذَ ‏ ‏فِي ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالْحَنْتَمِ ‏","","",""],[23776,23776,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَدَقَةُ بْنُ سَعِيدٍ الْحَنَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جُمَيْعُ بْنُ عُمَيْرٍ التَّيْمِيُّ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ مَعَ عَمَّتِي وَخَالَتِي إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَسَأَلْتُهَا كَيْفَ كَانَتْ إِحْدَاكُنَّ تَصْنَعُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏عَرَكَتْ ‏ ‏فَقَالَتْ كَانَ إِذَا كَانَ ذَلِكَ مِنْ إِحْدَانَا ‏ ‏ائْتَزَرَتْ بِالْإِزَارِ الْوَاسِعِ ثُمَّ الْتَزَمَتْ رَسُولَ اللَّهِ بِيَدَيْهَا ‏ ‏وَنَحْرِهَا ‏","","",""],[23777,23777,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏يَزِيدُ الرِّشْكُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا سَأَلَتْهَا أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى أَرْبَعًا قَالَتْ نَعَمْ أَرْبَعًا وَيَزِيدُ مَا شَاءَ اللَّهُ ‏","","",""],[23778,23778,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي عَتِيقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏تُحَدِّثُهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ السِّوَاكَ مَطْهَرَةٌ لِلْفَمِ مَرْضَاةٌ لِلرَّبِّ ‏","","",""],[23779,23779,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَائِمًا أَيَّامَ ‏ ‏الْعَشْرِ ‏ ‏قَطُّ ‏","","",""],[23780,23780,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ الَّذِي ‏ ‏قُبِضَ ‏ ‏فِيهِ ‏ ‏يَنْفُثُ ‏ ‏عَلَى نَفْسِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمُعَوِّذَاتِ فَلَمَّا ‏ ‏ثَقُلَ ‏ ‏عَنْ ذَلِكَ جَعَلْتُ أَنْفُثُ عَلَيْهِ بِهِنَّ وَأَمْسَحُهُ بِيَدِ نَفْسِهِ ‏","","",""],[23781,23781,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ السُّدِّيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا كُنْتُ أَقْضِي مَا يَكُونُ عَلَيَّ مِنْ رَمَضَانَ إِلَّا فِي شَعْبَانَ حَتَّى تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[23782,23782,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْقَاسِمُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَلَا هَذِهِ الْآيَةَ ‏ { ‏هُوَ الَّذِي أَنْزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ آيَاتٌ ‏ ‏مُحْكَمَاتٌ ‏ ‏هُنَّ أُمُّ الْكِتَابِ وَأُخَرُ ‏ ‏مُتَشَابِهَاتٌ ‏ ‏فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ ‏ ‏زَيْغٌ ‏ } ‏حَتَّى فَرَغَ مِنْهَا قَالَ قَدْ سَمَّاهُمْ اللَّهُ عَزَّ وَجَلَّ فَإِذَا رَأَيْتُمُوهُمْ فَاحْذَرُوهُمْ ‏","","",""],[23783,23783,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَيْشُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏شَبِيبِ بْنِ عَبْدِ الْمَلِكِ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏مُقَاتِلِ بْنِ حَيَّانَ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنَّا ‏ ‏نَنْبِذُ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غُدْوَةً فِي ‏ ‏سِقَاءٍ ‏ ‏وَلَا نُخَمِّرُهُ وَلَا نَجْعَلُ لَهُ عَكَرًا فَإِذَا أَمْسَى تَعَشَّى فَشَرِبَ عَلَى عَشَائِهِ فَإِنْ بَقِيَ شَيْءٌ فَرَّغْتُهُ أَوْ صَبَبْتُهُ ثُمَّ نَغْسِلُ ‏ ‏السِّقَاءَ ‏ ‏فَنَنْبِذُ فِيهِ مِنْ الْعِشَاءِ فَإِذَا أَصْبَحَ تَغَدَّى فَشَرِبَ عَلَى غَدَائِهِ فَإِنْ ‏ ‏فَضَلَ ‏ ‏شَيْءٌ صَبَبْتُهُ أَوْ فَرَّغْتُهُ ثُمَّ غَسَلَ ‏ ‏السِّقَاءَ ‏ ‏فَقِيلَ لَهُ أَفِيهِ غَسَلَ ‏ ‏السِّقَاءَ ‏ ‏مَرَّتَيْنِ قَالَ مَرَّتَيْنِ ‏","","",""],[23784,23784,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏قَالَتْ وَهِمَ ‏ ‏عُمَرُ ‏ ‏إِنَّمَا ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الصَّلَاةِ أَنْ ‏ ‏يُتَحَرَّى ‏ ‏طُلُوعُ الشَّمْسِ وَغُرُوبُهَا ‏","","",""],[23785,23785,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏أَهَلَّتْ ‏ ‏بِعُمْرَةٍ فَقَدِمَتْ وَلَمْ تَطُفْ ‏ ‏بِالْبَيْتِ ‏ ‏حَتَّى حَاضَتْ ‏ ‏فَنَسَكَتْ ‏ ‏الْمَنَاسِكَ ‏ ‏كُلَّهَا وَقَدْ ‏ ‏أَهَلَّتْ ‏ ‏بِالْحَجِّ فَقَالَ لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏النَّحْرِ ‏ ‏يَسَعُكِ طَوَافُكِ لِحَجِّكِ وَلِعُمْرَتِكِ فَأَبَتْ فَبَعَثَ بِهَا مَعَ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏إِلَى ‏ ‏التَّنْعِيمِ ‏ ‏فَاعْتَمَرَتْ بَعْدَ الْحَجِّ ‏","","",""],[23786,23786,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مَيْمُونِ بْنِ مِهْرَانَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَمِعَ الْمُنَادِيَ قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ ‏","","",""],[23787,23787,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الطِّيبِ ‏ ‏فِي مَفْرِقِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ أَيَّامٍ وَهُوَ مُحْرِمٌ ‏","","",""],[23788,23788,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا مَرِضَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذْتُ بِيَدِهِ فَجَعَلْتُ أُمِرُّهَا عَلَى صَدْرِهِ وَدَعَوْتُ بِهَذِهِ الْكَلِمَاتِ أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ فَانْتَزَعَ يَدَهُ مِنْ يَدِي وَقَالَ ‏ ‏أَسْأَلُ اللَّهَ عَزَّ وَجَلَّ الرَّفِيقَ الْأَعْلَى الْأَسْعَدَ ‏","","",""],[23789,23789,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْرُكُ الْمَنِيَّ مِنْ ثَوْبِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَذْهَبُ فَيُصَلِّي فِيهِ ‏","","",""],[23790,23790,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَعَلْتُمُونَا بِمَنْزِلَةِ الْكَلْبِ وَالْحِمَارِ لَقَدْ ‏ ‏رَأَيْتُنِي وَأَنَا تَحْتَ كِسَائِي بَيْنَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ الْقِبْلَةِ فَأَكْرَهُ أَنْ أَسْنَحَ بَيْنَ يَدَيْهِ حَتَّى ‏ ‏أَنْسَلَّ ‏ ‏مِنْ تَحْتِ ‏ ‏الْقَطِيفَةِ ‏ ‏انْسِلَالًا ‏","","",""],[23791,23791,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مِقْدَامِ بْنِ شُرَيْحِ بْنِ هَانِئٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهَا ‏ ‏أَنَّهُ سَمِعَهَا تَقُولُ ‏ ‏كُنْتُ عَلَى بَعِيرٍ ‏ ‏صَعْبٍ ‏ ‏فَجَعَلْتُ أَضْرِبُهُ فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكِ بِالرِّفْقِ فَإِنَّ الرِّفْقَ لَا يَكُونُ فِي شَيْءٍ إِلَّا زَانَهُ وَلَا ‏ ‏يُنْزَعُ ‏ ‏مِنْ شَيْءٍ إِلَّا ‏ ‏شَانَهُ ‏","","",""],[23792,23792,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏الْحَكَمُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏أَنَّهُ ‏ ‏كَانَ ‏ ‏نَازِلًا ‏ ‏عَلَى ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏إِنَّ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏النَّخَعِ ‏ ‏كَانَ ‏ ‏نَازِلًا ‏ ‏عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَاحْتَلَمَ فَأَبْصَرَتْهُ جَارِيَةٌ ‏ ‏لِعَائِشَةَ ‏ ‏وَهُوَ يَغْسِلُ أَثَرَ الْجَنَابَةِ مِنْ ثَوْبِهِ ‏ ‏أَوْ يَغْسِلُ ثَوْبَهُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏هَكَذَا قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَقَالَتْ لَقَدْ رَأَيْتُنِي وَمَا أَزِيدُ عَلَى أَنْ ‏ ‏أَفْرُكَهُ مِنْ ثَوْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَاه ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏أَنَّ ‏ ‏هَمَّامَ بْنَ الْحَارِثِ ‏ ‏كَانَ نَازِلًا عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[23793,23793,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا كَانَتْ تَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَدِّدُوا ‏ ‏وَقَارِبُوا ‏ ‏وَأَبْشِرُوا ‏ ‏فَإِنَّهُ لَنْ يُدْخِلَ الْجَنَّةَ أَحَدًا عَمَلُهُ قَالُوا وَلَا أَنْتَ يَا رَسُولَ اللَّهِ قَالَ وَلَا أَنَا إِلَّا أَنْ ‏ ‏يَتَغَمَّدَنِي ‏ ‏اللَّهُ عَزَّ وَجَلَّ مِنْهُ بِرَحْمَةٍ وَاعْلَمُوا أَنَّ أَحَبَّ الْعَمَلِ إِلَى اللَّهِ عَزَّ وَجَلَّ أَدْوَمُهُ وَإِنْ قَلَّ ‏","","",""],[23794,23794,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا زَالَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ يُوَرِّثُهُ ‏","","",""],[23795,23795,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏خَالِدُ بْنُ الْحَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏التَّبَتُّلِ ‏","","",""],[23796,23796,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ ‏ ‏جَهْدًا ‏ ‏شَدِيدًا يَكُونُ بَيْنَ يَدَيْ ‏ ‏الدَّجَّالِ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ فَأَيْنَ ‏ ‏الْعَرَبُ ‏ ‏يَوْمَئِذٍ قَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏الْعَرَبُ ‏ ‏يَوْمَئِذٍ قَلِيلٌ فَقُلْتُ مَا يُجْزِئُ الْمُؤْمِنِينَ يَوْمَئِذٍ مِنْ الطَّعَامِ قَالَ مَا يُجْزِئُ الْمَلَائِكَةَ التَّسْبِيحُ وَالتَّكْبِيرُ وَالتَّحْمِيدُ وَالتَّهْلِيلُ قُلْتُ فَأَيُّ الْمَالِ يَوْمَئِذٍ خَيْرٌ قَالَ غُلَامٌ شَدِيدٌ يَسْقِي أَهْلَهُ مِنْ الْمَاءِ وَأَمَّا الطَّعَامُ فَلَا طَعَامَ ‏","","",""],[23797,23797,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ خُمَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏أَرْسَلَنِي ‏ ‏مُدْرِكٌ ‏ ‏أَوْ ‏ ‏ابْنُ مُدْرِكٍ ‏ ‏إِلَى ‏ ‏عَائِشَةَ ‏ ‏أَسْأَلُهَا عَنْ أَشْيَاءَ قَالَ فَأَتَيْتُهَا فَإِذَا هِيَ تُصَلِّي الضُّحَى فَقُلْتُ أَقْعُدُ حَتَّى تَفْرُغَ فَقَالُوا هَيْهَاتَ ‏ ‏فَقُلْتُ لِآذِنِهَا كَيْفَ أَسْتَأْذِنُ عَلَيْهَا فَقَالَ قُلْ السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ السَّلَامُ عَلَى ‏ ‏أُمَّهَاتِ الْمُؤْمِنِينَ أَوْ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّلَامُ عَلَيْكُمْ قَالَ فَدَخَلْتُ عَلَيْهَا فَسَأَلْتُهَا فَقَالَتْ أَخُو ‏ ‏عَازِبٍ ‏ ‏نِعْمَ أَهْلُ الْبَيْتِ فَسَأَلْتُهَا عَنْ ‏ ‏الْوِصَالِ ‏ ‏فَقَالَتْ لَمَّا كَانَ يَوْمُ ‏ ‏أُحُدٍ ‏ ‏وَاصَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ فَشَقَّ عَلَيْهِمْ فَلَمَّا رَأَوْا الْهِلَالَ أَخْبَرُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَوْ زَادَ لَزِدْتُ فَقِيلَ لَهُ إِنَّكَ تَفْعَلُ ذَاكَ ‏ ‏أَوْ شَيْئًا نَحْوَهُ ‏ ‏قَالَ ‏ ‏إِنِّي لَسْتُ مِثْلَكُمْ إِنِّي أَبِيتُ يُطْعِمُنِي رَبِّي وَيَسْقِينِي وَسَأَلْتُهَا عَنْ الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ فَقَالَتْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ رَجُلًا عَلَى الصَّدَقَةِ قَالَتْ فَجَاءَتْهُ عِنْدَ الظُّهْرِ فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ وَشُغِلَ فِي قِسْمَتِهِ حَتَّى صَلَّى الْعَصْرَ ثُمَّ صَلَّاهَا وَقَالَتْ عَلَيْكُمْ بِقِيَامِ اللَّيْلِ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ لَا يَدَعُهُ فَإِنْ مَرِضَ قَرَأَ وَهُوَ قَاعِدٌ وَقَدْ عَرَفْتُ أَنَّ أَحَدَكُمْ يَقُولُ بِحَسْبِي أَنْ أُقِيمَ مَا كُتِبَ لِي وَأَنَّى لَهُ ذَلِكَ وَسَأَلْتُهَا عَنْ الْيَوْمِ الَّذِي يُخْتَلَفُ فِيهِ مِنْ رَمَضَانَ فَقَالَتْ لَأَنْ أَصُومَ يَوْمًا مِنْ شَعْبَانَ أَحَبُّ إِلَيَّ مِنْ أَنْ أُفْطِرَ يَوْمًا مِنْ رَمَضَانَ قَالَ فَخَرَجْتُ فَسَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏وَأَبَا هُرَيْرَةَ ‏ ‏فَكُلُّ وَاحِدٍ مِنْهُمَا قَالَ أَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْلَمُ بِذَاكَ مِنَّا ‏ ‏سَمِعْت ‏ ‏أَبِي ‏ ‏يَقُولُ ‏ ‏يَزِيدُ بْنُ خُمَيْرٍ ‏ ‏صَالِحُ الْحَدِيثِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُوسَى ‏ ‏هُوَ خَطَأٌ أَخْطَأَ فِيهِ ‏ ‏شُعْبَةُ ‏ ‏هُوَ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي قَيْسٍ ‏","","",""],[23798,23798,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا ‏ ‏عَادَ ‏ ‏مَرِيضًا مَسَحَهُ بِيَدِهِ وَقَالَ ‏ ‏أَذْهِبْ ‏ ‏الْبَاسَ ‏ ‏رَبَّ النَّاسِ وَاشْفِ أَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا ‏ ‏يُغَادِرُ ‏ ‏سَقَمًا ‏ ‏فَلَمَّا مَرِضَ مَرَضَهُ الَّذِي مَاتَ فِيهِ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏أَخَذْتُ بِيَدِهِ فَذَهَبْتُ لِأَقُولَ فَانْتَزَعَ يَدَهُ وَقَالَ اللَّهُمَّ اغْفِرْ لِي وَاجْعَلْنِي فِي الرَّفِيقِ الْأَعْلَى ‏","","",""],[23799,23799,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَفْصٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏مَا يَقْطَعُ الصَّلَاةَ قَالَ فَقُلْنَا الْحِمَارُ وَالْمَرْأَةُ قَالَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏إِنَّ الْمَرْأَةَ إِذًا لَدَابَّةُ سُوءٍ لَقَدْ ‏ ‏رَأَيْتُنِي بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُعْتَرِضَةً كَاعْتِرَاضِ الْجَنَازَةِ وَهُوَ ‏ ‏يُصَلِّي ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏بَيْنَهُ وَبَيْنَ الْقِبْلَةِ فِيمَا أَظُنُّ ‏","","",""],[23800,23800,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏كَيْفَ كَانَ يَصْنَعُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ كَانَ ‏ ‏يَكُونُ فِي مِهْنَةِ أَهْلِهِ فَإِذَا حَضَرَتْ الصَّلَاةُ خَرَجَ فَصَلَّى ‏","","",""]];
